-- 3. approve_shops.sql
-- Chuyển trạng thái 3 gian hàng từ PENDING sang APPROVED.
-- Đồng thời ghi lịch sử phê duyệt vào shop_approval_history.
BEGIN;

DO $$
DECLARE
    v_count INTEGER;
    v_admin_id BIGINT := 99;
BEGIN
    -- Kiểm tra số lượng shop đang chờ duyệt
    SELECT COUNT(*)
    INTO v_count
    FROM marketplace.shops
    WHERE shop_id IN (1, 2, 3)
      AND shop_status = 'PENDING';

    -- Phải có đúng 3 shop đang chờ duyệt
    IF v_count <> 3 THEN
        RAISE EXCEPTION
            'Cần 3 shop PENDING, hiện có %', v_count;
    END IF;

    -- Phê duyệt shop và ghi lịch sử
    WITH approved AS (
        UPDATE marketplace.shops
        SET
            shop_status = 'APPROVED',
            updated_at = NOW()
        WHERE shop_id IN (1, 2, 3)
          AND shop_status = 'PENDING'
        RETURNING shop_id
    )
    INSERT INTO marketplace.shop_approval_history (
        shop_id,
        admin_user_id,
        old_status,
        new_status,
        reason
    )
    SELECT
        shop_id,
        v_admin_id,
        'PENDING',
        'APPROVED',
        'Admin phê duyệt gian hàng COCO'
    FROM approved;

END $$;

COMMIT;

