('3', '1', 'COCO-S03-C01-0001', 'Kem Rửa Mặt Hada Labo Sạch Sâu Dưỡng Ẩm 80g Hasaki Sản Phẩm Chính Hãng', 'Kem Rửa Mặt Hada Labo Sạch Sâu Dưỡng Ẩm Da là sản phẩm sữa rửa mặt nằm trong dòng dưỡng ẩm Advanced Nourish của Hada Labo, với kết cấu dạng kem tạo bọt mịn, nhẹ nhàng len lỏi sâu vào lỗ chân lông để loại bỏ bụi bẩn & bã nhờn, đồng thời kết hợp hệ dưỡng ẩm sâu HA, SHA, Nano HA giúp cung cấp độ ẩm cho da luôn ẩm mượt và sạch sâu suốt 36 giờ.', '81000'),
('1', '2', 'COCO-S01-C02-0001', 'Nước tẩy trang và làm sạch sâu 3-in-1 L''Oreal Paris Micellar Water 400ml', 'Dòng sản phẩm Nước Tẩy Trang L''Oréal Paris hiện có 6 PHÂN LOẠI phù hợp cho từng nhu cầu khác nhau cho bạn lựa chọn:
 ● [MỚI] Nước tẩy trang dành cho da nhạy cảm và đang phục hồi L''Oreal Paris Amino Micellar Water 400ml (Xanh bạc): 11 Amino Acid giúp làm sạch sâu, nuôi dưỡng hàng rào bảo vệ da
 ● L''Oréal Paris Micellar Water 3-in-1 Refreshing Even For Sensitive Skin (Xanh dương nhạt): Giúp làm sạch lớp trang điểm và làm tươi mát da. Dành cho da dầu/da hỗn hợp. Phù hợp với cả da nhạy cảm.
 ● L''Oréal Paris Micellar Water 3-in-1 Moisturizing Even For Sensitive Skin (Hồng): Giúp làm sạch lớp trang điểm và dưỡng ẩm da. Dành cho da thường/da khô. Phù hợp với cả da nhạy cảm.
 ● L''Oréal Paris Micellar Water 3-in-1 Deep Cleansing Even For Sensitive Skin (Xanh dương đậm): Có hai lớp chất lỏng giúp hòa tan chất bẩn và loại bỏ toàn bộ lớp trang điểm hiệu quả, kể cả lớp trang điểm lâu trôi và không thấm nước chỉ trong một bước.
 ● L''Oréal Paris Revitalift Crystal Purifying Micellar Water (Trắng): Làm sạch sâu lỗ chân lông và kiềm dầu cho làn da sáng mịn rạng rỡ. Dành cho da dầu.
 ● L''Oreal Paris Revitalift Hyaluronic Acid Hydrating Micellar Water (Tím): Làm sạch và cấp ẩm cho làn da căng mịn từ bên trong. Dành cho da khô & hỗn hợp.
 VÌ SAO BẠN SẼ THÍCH? [MỚI] L''OREAL PARIS AMINO MICELLAR WATER
 Khi làn da bạn trở nên nhạy cảm, dễ kích ứng, hoặc đang cần phục hồi, việc làm sạch đòi hỏi sự dịu nhẹ tối đa nhưng vẫn phải hiệu quả. Điểm đặc biệt của sản phẩm là công thức đột phá chứa 11 loại Amino Acid, không chỉ giúp làm sạch sâu lớp trang điểm và bụi bẩn mà còn nuôi dưỡng và củng cố hàng rào bảo vệ da. Các Amino Acid này tăng cường khả năng giữ ẩm tự nhiên, làm dịu da và hỗ trợ quá trình phục hồi.
 Với pH trung tính (pH=7) và cam kết không chứa hương liệu, cồn, chất tạo màu hay Lanolin, sản phẩm cực kỳ dịu nhẹ, đảm bảo không gây kích ứng. Kết quả khảo sát cho thấy, phần lớn người dùng công nhận sản phẩm làm sạch hiệu quả, không gây kích ứng và giúp da ẩm mượt sau khi dùng.
 Hãy biến bước làm sạch thành bước dưỡng da chuyên sâu với L''Oréal Paris Amino Micellar Water để làn da bạn luôn sạch khỏe và mềm mại.
 ƯU ĐIỂM NỔI BẬT
 - Làm sạch hiệu quả, dịu nhẹ: Công nghệ Micellar với các phân tử Micelle hút sạch lớp trang điểm và bụi bẩn, cùng với Polyol giúp loại bỏ cặn bẩn từ sâu lỗ chân lông, đảm bảo da sạch thoáng mà không gây khô căng.
 - Hỗ trợ phục hồi và bảo vệ da: Nhờ 11 loại Amino Acid, sản phẩm không chỉ làm dịu da, giảm viêm ngứa mà còn hỗ trợ quá trình tái tạo những tổn thương nhỏ, giúp da khỏe mạnh hơn.
 - Phù hợp cho da nhạy cảm: Với pH trung tính (pH=7) tương tự nước mắt, và cam kết không chứa hương liệu, cồn, chất tạo màu, hay Lanolin, sản phẩm giảm thiểu tối đa nguy cơ kích ứng.
 HIỆU QUẢ SỬ DỤNG
 Được kiểm nghiệm và tin dùng: Theo khảo sát, 98.4% người dùng công nhận sản phẩm không gây kích ứng, 96.9% thấy hiệu quả làm sạch và 90.6% cảm nhận da được dưỡng ẩm sau khi sử dụng.
 HƯỚNG DẪN SỬ DỤNG:
 ● Lắc đều.
 ● Cho sản phẩm vào bông tẩy trang rồi nhẹ nhàng lau lên mặt, mắt và môi theo chuyển động tròn.
 THÀNH PHẦN CHÍNH:
 Aqua / Water, Hexylene Glycol, Glycerin, Poloxamer 184, Disodium Cocoamphodiacetate, Chlorphenesin, Phytic Acid, Myrtrimonium Bromide, Potassium Hydroxide, Sodium Pca, Sodium Lactate, Arginine, Aspartic Acid, Pca, Glycine, Alanine, Serine, Valine, Threonine, Isoleucine, Proline, Phenylalanine, Histidine
 HƯỚNG DẪN BẢO QUẢN:
 Nơi khô ráo, thoáng mát.
 Tránh ánh nắng trực tiếp, nơi có nhiệt độ cao hoặc ẩm ướt.
 Đậy nắp kín sau khi sử dụng.
 Bao bì thay đổi theo từng đợt nhập hàng.
 Thương hiệu: L''oreal Paris
 Chất liệu: nước tẩy trang
 Trọng lượng/kích thước 400ml
 1. Xuất xứ: Trung Quốc
 2. HSD: 3 năm kể từ ngày sản xuất
 3. NSX: "Xem trên bao bì"
 4. Dung tích: 400ml', '209000'),
('2', '2', 'COCO-S02-C02-0001', '[FREESHIP XTRA] Son dưỡng Astrid tái tạo môi từ mỡ hươu', '❌ Son mỡ hươu Astrid - giúp môi khi nứt nẻ (em nhỏ nhưng chất như Nước cất) 💋💋
 💧 Mỡ Hươu vào mùa hanh khô này thì chẳng lo gì khi có em ý luôn!
 💧 Ko còn tình trạng khô môi + nứt nẻ + bong da khó chịu
 Sau 2h môi bạn sẽ trở lại trạng thái bóng Mịn, căng bóng.
 Cứ dùng sẽ có sự cảm nhận rõ ràng luôn nha.
 Giá chỉ #40k thỏi to
 DƯỠNG MÔI MỠ HƯƠU ARTRIS-hàng Sec
 Dùng dc cả mùa đông
