 +Môi Bạn sẽ Căng Mọng Bóng
 sau 2 ngày sử dụng
 + Không còn Tình Trạng môi căng, Thô ráp hay nứt nẻ
 + Khi Thoa Ko bị cảm giác Bì môi , Môi Khó thở như các loại dưỡng môi khác
 ------------------------------------
 Cách Sử dụng:
 1/ -Trước khi Đi ngủ bạn thoa 1 Lớp nhu thoa son
 Sáng hôm sau bạn trà cọ rửa vào môi thì da môi sẽ bong sạch lợp da chết nha.
