 Cả ngày bạn nên mang theo son trong túi sách nha.
 *cư như vậy cả mùa đông môi bạn sẽ không với đôi môi khô cứng
 – Ưu điểm:
 Em này giá phải nói là cực rẻ luôn, bình dân thật sự
 Công dụng dưỡng môi đỉnh, không thua kém các son xịn
 Thiết kế chắc tay
 Mùi chanh khá dễ chịu
 – Nhược điểm:
 Chất son hơi lỏng, dễ chị chảy khi vào hè
 Khá bóng mỡ và nặng môi khi thoa lên, không quá phù hợp để sử dụng làm son lót
 Với phiên bản mini, bạn không thể vặn lên xuống thỏi son được.
 Size đại 19G: Khuyên dùng cho da body tay chân, không dùng cho môi 
