('3', '5', 'COCO-S03-C05-0001', 'Máy Massage Bấm huyệt Xung Điện với 4 miếng dán', 'Máy Massage Bấm huyệt Xung Điện với 4 miếng dán VỀ HÀNG RÙI MN ƠI , 
 HÀNG CẬP NHẬT TỪ NGÀY 15/6/2023 Ạ
 thông tin sản phẩm : ❤️Bộ sản phẩn gồm 1 củ sạc. 1 dây nối củ sạc, 3 cục pin aaa ,4 miếng dán 1 dây dẫn từ máy vào 4 miếng dán , xoá tan mệt mỏi thường ngày loại bỏ các cơn đau nhức tăng cường sức khoẻ
 Một ngày bạn có tới 8 tiếng ngồi ở bàn làm việc, miệt mài bên chiếc máy tính. Thời gian còn lại bạn ở trên đường, ở nhà bếp nấu ăn, giặt quần áo, dọn dẹp nhà cửa… biết bao công việc khiến bạn mệt nhoài. Đến cuối ngày chỉ muốn nằm lăn ra giường vì lưng đã mỏi nhừ và cánh tay ê buốt. Nào hãy thư giãn nhé. Cắm ngay chiếc máy massage để chấm dứt ngay mấy cơn đau này để rồi có giấc ngủ thật ngon.
 Xóa tan những cơn đau – bạn dường như đã thấy chiếc máy này rất tuyệt vời rồi phải không, nhưng thực sự chiếc mày này còn có công dụng lớn hơn rất nhiều. Chiếc máy góp phần chữa trị rất nhiều căn bệnh mà chúng ta như: Bị cảm, đau dạ dày, táo bón, đau bụng, đột quỵt, bán thân bất toaị, cao huyết áp, nhức đầu, viêm khớp dạng thấp, cứng cổ, viêm quanh khớp vai – cánh tay, kinh nguyệt bất thường, rối loạn hoạt động tình dục ở nam…
 Máy kết hợp phương pháp massage cổ truyền với hiện đại, giúp giảm đau cơ, mệt mỏi, tạo cảm giác thư giãn và tăng cường tuần hoàn máu.
 Khi sắm chiếc máy này bạn sẽ có sự hướng dẫn thật chi tiết cách sử dụng cho mỗi bệnh bởi những chế độ khác nhau. Máy có rất nhiều chế độ: Châm cứu, đấm bóp, xoa bóp, giác hơi, co cơ, giảm cân…MÁY Trị LIỆU có các nút chức năng dùng tiếng Việt và có sách hướng dẫn tiếng Việt giúp các bạn dễ dàng 
 lưu ý : sản phẩm xung điện 4 miếng dán chỉ hoạt động khi dán cả 4 miếng dán, độ rung phụ thuộc vào cường độ có sẵn trên thao tác sản phẩm từ mức 1 đến mức 15, mức 1 là mức nhỏ nhất , 1 số đối tượng sức khỏe bình thường, không bị các bệnh về cơ xương khớp sẽ có thể có cảm giác rung nhẹ ( 1 số người gọi là giật) thực chất là sp rung ,
 shop không đồng ý yêu cầu trả hàng với lý do sp chạy yếu/rung nhẹ .. vì cường độ hoạt động của từng cá nhân đáp ứng với máy ở mức độ khác nhau
 LƯU Ý: b nhận hàng vui lòng quay video khi bắt đầu bóc đồ ( thể hiện rõ mã đơn hàng, kiện hàng còn nguyên vẹn các mặt trc khi bóc, và KHÔNG nhận hàng đã bị mở, móp méo ) để nếu shop có giao thiếu hay giao nhầm đồ, hay lỗi shop sẽ giải quyết và gửi lại hàng ạ 😍 Nếu b không quay lại video shop xin từ chối giải quyết ạ !!', '98000'),
('3', '2', 'COCO-S03-C02-0001', 'Nước làm sạch sâu và tẩy trang cho da nhạy cảm La Roche-Posay Micellar Water Ultra Sensitive Skin 400ml', '*BAO BÌ CÓ SỰ THAY ĐỔI TÙY THEO ĐỢT NHẬP HÀNG
   • VÌ SAO BẠN SẼ THÍCH? 
 Nước tẩy trang dành cho da nhạy cảm La Roche-Posay Micellar Water Ultra Sensitive Skin với công nghệ cải tiến Glyco Micellar mang lại khả năng làm sạch hiệu quả, giúp lấy đi lớp trang điểm, bã nhờn hiệu quả nhưng vẫn dịu nhẹ cho làn da nhạy cảm. Thành phần giàu GLYCERIN giúp dưỡng ẩm làm mềm da, giảm ma sát khi làm sạch. Nước khoáng La Roche-Posay làm dịu da. Sản phẩm phù hợp để tẩy trang cho vùng mặt, mắt và môi
 THÔNG TIN SẢN PHẨM
 Loại sản phẩm
 - Nước tẩy trang công nghệ cải tiến Glyco Micellar mang lại hiệu quả làm sạch hiệu quả cho da nhạy cảm.
