 - Phù hợp cho nhiều loại da, đặc biệt là da nhạy cảm.
 Độ an toàn
 - Không paraben / Không chất tạo màu / Không cồn/ Không chứa xà phòng.
 Thành phần
 - Công nghệ cải tiến Glyco Micellar mang lại khả năng làm sạch hiệu quả hiệu quả.
 - GLYCERIN giúp dưỡng ẩm và làm mềm da.
 - Nước khoáng La Roche-Posay giàu selenium, giúp làm dịu da, giảm kích ứng.
 • HIỆU QUẢ SỬ DỤNG
 - Làm sạch đến 99% lớp trang điểm,70% mascara*.
 * Thử nghiệm thực hiện trên 20 tình nguyện viên được đánh giá sau khi sử dụng sản phẩm để tẩy trang lớp trang điểm nền, mascara
 • HƯỚNG DẪN SỬ DỤNG
