('1', '2', 'COCO-S01-C02-0002', 'Nước làm sạch sâu và tẩy trang dành cho da dầu Effaclar Micellar Water 400ml', 'THÔNG TIN SẢN PHẨM 
 Nước tẩy trang giúp nhẹ nhàng làm sạch da La Roche-Posay Effaclar Micellar Water Ultra Oily Skin với công nghệ Glyco Micellar mang lại hiệu quả làm sạch hiệu quả, giúp lấy đi lớp trang điểm, bã nhờn và các hạt bụi nhỏ nhưng vẫn dịu nhẹ cho làn da dầu nhạy cảm. 
 Loại sản phẩm 
 - Nước tẩy trang công nghệ cải tiến Glyco Micellar và giảm dầu cho da dầu nhạy cảm. 
 Loại da phù hợp 
 - Phù hợp cho da dầu nhạy cảm. 
 Độ an toàn 
 - Không paraben/ Không chất tạo màu/ Không cồn/ Không chứa xà phòng. 
 - Duy trì độ pH tự nhiên của da phù hợp cho da dầu, nhạy cảm. 
 Thành phần 
 - Công nghệ Glyco Micellar mang lại hiệu quả làm sạch. 
 - ZINC PCA (kẽm) giúp giảm dầu giảm bã nhờn. 
 - Nước khoáng La Roche-Posay giúp làm dịu da. 
 ƯU ĐIỂM NỔI BẬT 
 - Giúp làm sạch và dưỡng ẩm cho da. 
 HƯỚNG DẪN SỬ DỤNG 
 - Dùng bông cotton thoa sản phẩm lên mặt, mắt và môi. 
 - Không cần rửa lại bằng nước. 
 HSD: 03 năm kể từ NSX 
 NSX: Xem trên bao bì 
 Xuất xứ thương hiệu: Pháp 
 Nơi sản xuất: Pháp', '478800'),
('2', '1', 'COCO-S02-C01-0002', 'Mặt Nạ Mediheal Dưỡng Trắng Da, Giảm Mụn, Tái Tạo Và Phục Hồi Da', 'Mặt Nạ Dưỡng Da MEDIHEAL Essential
 Thương hiệu: Mediheal
 Xuất xứ: Hàn Quốc
 Dung tích 25ml
 +++ Tất cả mặt nạ của Mediheal đều được là mặt nạ lụa gel, không phải mặt nạ giấy thông thường nên khi đắp lên đã tạo cảm giác thoải mái, thư giãn cho da, ngoài ra mặt nạ bọng tinh chất và ôm khít mặt nên bạn có thể sử dụng trong lúc làm việc hoặc đi lại, ngồi cũng không sao.
 Phân loại các mặt nạ Mediheal
 1. H.D.P - Mặt Nạ Than Hoạt Tính: 25ml
 Cung cấp khoáng chất cho da, điều chỉnh việc bài tiết dầu và kiểm soát mụn trên da đồng thời có tác dụng se khít lỗ chân long, cho làn da mềm mịn.
 2. W.H.P - Mặt nạ White Hydrating Charcoal-Mineral Mask : 25ml
 Làm trắng da, cung cấp độ ẩm tối ưu cho da, cấp nước cho da duy trì độ ẩm sâu, nuôi dưỡng làn da căng mượt, mịn màng tràn đầy sức sống.
 3. I.P.I - Lightmax Ampoule Mask: 27ml
 Giúp làm sáng da bằng cách phá hủy melanin trên bề mặt da va cung cấp độ ẩm cho da mềm mại.
 Giúp cho làn da của bạn sáng hơn vượt trội, cung cấp dưỡng chất và dưỡng ẩm cho da, giúp cải thiện làn da xỉn màu rõ rệt.', '39500'),
('3', '1', 'COCO-S03-C01-0002', 'Gel rửa mặt cho da dầu nhạy cảm La Roche-Posay Effaclar Foaming Gel 400ml', 'Gel rửa mặt tạo bọt giúp làm sạch hiệu quả và hỗ trợ giảm mụn và giảm dầu nhờn cho da dầu mụn La Roche-Posay Effaclar Purifying Foaming Gel. Với kết cấu dạng gel trong suốt, dễ dàng tạo bọt cùng công thức không chứa xà phòng, dịu nhẹ cho da, sản phẩm nhẹ nhàng làm sạch hiệu quả, làm sạch bụi bẩn cùng dầu thừa. Đồng thời sản phẩm có độ pH ở mức cân bằng 5.0 nên sau khi rửa mặt xong, da không hề khô rít, căng rát, mà vẫn mềm mịn, sạch thoáng.
 THÔNG TIN SẢN PHẨM:
 Loại sản phẩm
 - Sữa rửa mặt tạo bọt dạng gel làm sạch hiệu quả giúp hỗ trợ giảm mụn và giảm dầu.
 Loại da phù hợp
 - Dành cho da mụn và da dễ nổi mụn.
 Độ an toàn
 - Độ pH cân bằng 5.0
 - Không chứa xà phòng, không chứa cồn, không chất tạo màu và không paraben.
 Thành phần
 - ZINC PCA (kẽm) giúp làm sạch dầu thừa hiệu quả
 - Nước khoáng La Roche-Posay (giàu Selenium) giúp mang lại cảm giác dịu nhẹ cho da.
 - Công thức được lựa chọn kĩ càng với các thành phần làm sạch dịu nhẹ phù hợp cho da dầu và da mụn nhạy cảm.
 • ƯU ĐIỂM NỔI BẬT
 Nhẹ nhàng làm sạch bụi bẩn và bã nhờn dư thừa, hỗ trợ giảm mụn, mang lại làn da sạch và thoáng mát.
 • HIỆU QUẢ SỬ DỤNG
 Làm sạch bụi bẩn và bã nhờn
 • HƯỚNG DẪN SỬ DỤNG
 - Sử dụng sữa rửa mặt hằng ngày vào buổi sáng và tối. 
 - Làm ẩm da với nước ấm, lấy một lượng vừa đủ sữa rửa mặt ra tay, tạo bọt với nước rồi thoa sữa rửa mặt lên mặt, tránh vùng da quanh mắt
 - Massage nhẹ nhàng, sau đó rửa sạch lại với nước và lau khô.
 HSD: 03 năm kể từ NSX
 NSX: Xem trên bao bì
 Xuất xứ thương hiệu: Pháp
 Nơi sản xuất: Pháp', '558360'),
('1', '5', 'COCO-S01-C05-0002', 'Cây Gãi Lưng Inox Kéo Dài Rút Gọn 50Cm - Tay Dụng Cụ Đồ Gãi Ngứa Siêu Đỉnh', 'Cây gãi lưng dạng rút gọn, thân inox có thể kéo dài khoảng 50 cm và đầu gãi hình bàn tay. Dùng hỗ trợ gãi những vùng lưng khó với tới; có thể thu ngắn để cất giữ.', '13399'),
('1', '1', 'COCO-S01-C01-0003', 'Sữa rửa mặt dưỡng ẩm tối ưu Hada Labo Advanced Nourish Cleanser 80g', 'Tên model: Kem rửa mặt dưỡng ẩm tối ưu Hada Labo Advanced Nourish Cleanser 80g
 Thành phần chính và công dụng: Kem rửa mặt Hada Labo dưỡng ẩm với công dụng làm sạch sâu cùng hệ dưỡng ẩm sâu giúp dưỡng da ẩm mượt, sáng mịn, tươi trẻ mỗi ngày
 - Bọt mịn nhẹ nhàng rửa sạch lớp tế bào chết, bụi bẫn, bã nhờn ẩn sâu trong lỗ chân lông.
 - Hệ dưỡng ẩm sâu HA, SHA, Nano HA cung cấp độ ẩm tối ưu cho các lớp biểu bì, khắc phục tình trạng khô sạm do mất nước, tái tạo cấu trúc đàn hồi cho làn da luôn ẩm mượt, sáng mịn.
 - HA (Hyaluronic Acid): Kem rửa mặt Hada Labo dưỡng ẩm chứa 1 gram HA với khả năng ngậm hàng triệu phân tử nước, tạo màng dưỡng dưỡng ẩm bảo vệ da.
 - SHA (Super Hyaluronic Acid): ngậm nước gấp 2 lần HA, nhẹ nhàng thấm sâu và giữ nước lâu hơn cho tế bào da vùng trung bì.
 - Nano HA (Nano Hyaluronic Acid): có kích thước phân tử cực nhỏ, chỉ bằng 1/20 HA, dễ dàng len lõi đến lớp hạ bì, dưỡng ẩm sâu hơn.
 Hướng dẫn sử dụng:
 - Sau khi tẩy trang, làm ướt mặt, cho một lượng kem rửa mặt Hada Labo dưỡng ẩm vừa đủ vào lòng bàn tay, tạo bọt
 - Thoa đều bọt lên da mặt và kết hợp massage nhẹ nhàng theo chiều kết cấu da. Rửa sạch lại với nước
 * Nên dùng kết hợp kem rửa mặt Hada Labo dưỡng ẩm với Dung dịch/ Kem dưỡng ẩm Hada Labo ADVANCED NOURISH để đạt hiệu quả tối ưu.
 Đối tượng sử dụng:
 - Dành cho mọi loại da
 - Dành cho làn da khô, thiếu ẩm
 - Dành cho làn da thường có tình trạng khô căng sau khi rửa mặt
 Thông tin thương hiệu:
 - Thương hiệu Hada Labo thuộc công ty Rohto Mentholatum Việt Nam
 - Xuất xứ thương hiệu: Nhật Bản
 - Sản xuất tại: Việt Nam
 - Hạn sử dụng: 4 năm kể từ ngày sản xuất
 - Ngày sản xuất: xem chi tiết trên vỏ hộp
