('2', '2', 'COCO-S02-C02-0002', 'Nước Tẩy Trang Garnier Micellar Cleansing Water Chính Hãng Đủ Mẫu 50ml, 125ml – 400ml', 'Nước Tẩy Trang Garnier Micellar Water
 Thương hiệu: Garnier Skin Naturals
 - Nước Tẩy Trang Dành Cho Da Xỉn Màu, Da Thường, Nhạy Cảm Garnier Micellar Cleansing Water Vitamin C For Dull & Sensitive Skin 50ml, 125ml, 400ml
 - Nước tẩy trang Garnier Màu Vàng kết hợp giữa nước và dầu thích hợp sử dụng cho da khô và nhạy cảm, tẩy sạch các sản phẩm make-up waterproof.
 - Nước tẩy trang Garnier Vitamin C làm sáng da rạng rỡ
 - Garnier Micellar Cleansing Water Combination To Oily and Sensitive Skin (nắp trắng, vỏ xanh) cho da hỗn hợp thiên dầu nhạy cảm.
 - Garnier Micellar Oily – Infused Cleansing Water Dry and Sensitive Skin (nắp trắng, lớp dầu màu vàng phía trên) cho da khô nhạy cảm.
 Garnier Micellar Cleansing Water ứng dụng công nghệ Micellar như một nam châm giúp làm sạch sâu lỗ chân lông, lấy đi dầu thừa và lớp trang điểm trên mặt trong một lần sử dụng.
 Nhờ bảng thành phần không chứa hương liệu, không chất bảo quản và cũng không chứa cồn, nên nước tẩy trang Garnier có thể dùng cho vùng da mắt và môi nhạy cảm.
 Garnier Micellar Cleansing Water cũng không hề để lại lớp bóng dầu như các loại tẩy trang khác, nên dù không thể rửa lại ngay với nước sau khi tẩy trang, làn da của các cô gái cũng đã được làm sạch “tuyệt đối”, không nhờn dính và không khô căng rát chút nào.
 Nước tẩy trang Garnier Micellar Cleansing Water sẽ giúp bước tẩy trang trong chu trình làm sạch da của các cô gái được “đơn giản hóa” và nhanh chóng hơn rất nhiều.
 Cách sử dụng:
 -Thấm dung dịch nước tẩy trang Garnier Micellar ra bông tẩy trang cotton.Sau đó lau lên vùng da make up để phân tử micellar nhanh chóng lấy đi cặn trang điểm, bụi bẩn và bã nhờn dưới da
 (Lưu ý: Sản phẩm Có thể không cần rửa lại với nước, tuy nhiên để chăm sóc da tốt nhất bạn nên rửa với sữa rửa mặt phù hợp, sau đó tiếp tục các bước chăm sóc da thường ngày)
 Thành phần:
 Aqua / Nước, Hexylene Glycol, Glycerin, Disodium Cocoamphodiacetate, Disodium Edta, Poloxamer 184, Thuộc Nhóm Biguanid Polyaminopropyl.
 - Micellar Water: Là Dạng Nước Tẩy Trang Ứng Dụng Công Nghệ Mixen Với Các Phân Tử Có Đầu Ưa Nước Và Đầu Ưa Dầu (Kị Nước). Đầu Ưa Dầu Giúp Lấy Đi Lớp Makeup, Còn Đầu Ưa Nước Bám Chặt Vào Bông Tẩy Trang Giúp Lấy Đi Các Cặn Trang Điểm;Nằm Sâu Bên Trong Lỗ Chân Lông Đồng Thời Cấp Nước Cho Da.
 - Glycerin: Giúp Cung Cấp Độ Ẩm Cho Da, Giúp Da Mềm Mịn Sau Khi Tẩy Trang.
 - Hexylene Glycol: Giúp Giữ Ẩm Cho Làn Da.
 - Disodium Edta:Giúp Tăng Cường Hiệu Quả Của Các Chất Bảo Quản Bằng Cách Ổn Định Độ Ph Cho Sản Phẩm.
 Thành Phần Không Có Chất Tạo Màu (Perfume), Chất Tạo Mùi (Fragrance), Paraben Và Mineral Oil Nên Rất An Toàn Cho Da.
 #garnierchinhhang #ukmart', '213000'),
('3', '2', 'COCO-S03-C02-0002', '[MUA 1 TẶNG 1 - QUÀ GIỚI HẠN] Nước Tẩy Trang L''oreal Dành Cho Da Dầu, Da Nhạy Cảm, Làm Sạch Trang Điểm 400ml Hasaki', 'Nước Tẩy Trang L''Oréal là dòng sản phẩm tẩy trang dạng nước đến từ L''Oreal Paris, được ứng dụng công nghệ Micellar dịu nhẹ giúp làm sạch da, lấy đi bụi bẩn, dầu thừa và cặn trang điểm chỉ trong một bước, mang lại làn da thông thoáng, mềm mượt mà không hề khô căng.
 Dòng sản phẩm Nước Tẩy Trang L''Oréal Paris hiện đã có mặt tại Hasaki với 5 phân loại phù hợp cho từng nhu cầu khác nhau cho bạn lựa chọn:
 Lưu ý: Hiện Hasaki đang bán song song cả 2 mẫu cũ và mới.
 1. Nước Tẩy Trang L''Oreal Tươi Mát Cho Da Dầu, Hỗn Hợp Micellar Water 3-in-1 Refreshing Even For Sensitive Skin (Xanh dương nhạt): Giúp làm sạch lớp trang điểm và làm tươi mát da. 
 - Dành cho những ai sở hữu làn da dầu nhờn muốn tìm một sản phẩm tẩy trang thoáng nhẹ, không để lại cảm giác nhờn dính sau khi làm sạch.
 - Sản phẩm phù hợp cho da dầu/da hỗn hợp, kể cả da nhạy cảm.
 2. Nước Tẩy Trang L''Oreal Dưỡng Ẩm Cho Da Thường, Khô Micellar Water 3-in-1 Moisturizing Even For Sensitive Skin (Hồng): Giúp làm sạch lớp trang điểm và dưỡng ẩm da. 
 - Dành cho những ai sở hữu làn da thiếu độ ẩm - thiếu nước, thường xuyên có cảm giác khô căng, bong tróc sau khi làm sạch.
 - Dành cho da thường/da khô. Phù hợp với cả da nhạy cảm. 
 3. Nước Tẩy Trang L''Oreal Làm Sạch Sâu Trang Điểm Micellar Water 3-in-1 Deep Cleansing Even For Sensitive Skin (Xanh dương đậm): Có hai lớp chất lỏng giúp hòa tan chất bẩn và loại bỏ toàn bộ lớp trang điểm hiệu quả, kể cả lớp trang điểm lâu trôi và không thấm nước chỉ trong một bước.
 - Dành cho những ai thường xuyên trang điểm, đặc biệt là lớp trang điểm lì, lâu trôi.
 - Sản phẩm phù hợp cho mọi loại da, kể cả da nhạy cảm.
 4. Nước Tẩy Trang L''Oréal Làm Sạch Sâu Cho Da Dầu Revitalift Crystal Purifying Micellar Water For Oily Skin (Bạc): Làm sạch sâu lỗ chân lông và kiềm dầu.
 Giải pháp cho tình trạng da:
 - Da dầu thừa - lỗ chân lông to, dễ bít tắc, dễ nổi mụn.
 - Da thiếu nước - thiếu ẩm, thô ráp, sần sùi.
 - Da xỉn màu & thâm sạm, kém rạng rỡ.
 - Sản phẩm phù hợp cho da dầu, hỗn hợp thiên dầu.
 5. Nước Tẩy Trang L''Oreal Căng Mịn Da Revitalift Hyaluronic Acid Hydrating Micellar Water (Tím): Làm sạch và cấp ẩm cho làn da căng mịn từ bên trong.
 Giải pháp cho tình trạng da:
 - Da thiếu nước - thiếu ẩm.
 - Da lão hoá, nếp nhăn.
 - Dành cho da khô & hỗn hợp.
 Hướng dẫn bảo quản Nước Tẩy Trang L''Oréal Paris Micellar Water:
 - Nơi khô ráo, thoáng mát.
 - Tránh ánh nắng trực tiếp, nơi có nhiệt độ cao hoặc ẩm ướt.
 - Đậy nắp kín sau khi sử dụng.
 Lưu ý:
 - Ngày sản xuất: Xem trên bao bì.
 - Hạn sử dụng: 03 năm kể từ ngày sản xuất.
 - Dung tích: 400ml (Mã lẽ) , 400ml + mini 95ml (Mã + quà tặng)
 Hướng dẫn sử dụng
 - Lắc đều sản phẩm Nước Tẩy Trang L''Oreal trước khi sử dụng.
 - Đổ nước tẩy trang thấm ướt vừa đủ lên miếng bông tẩy trang.
 - Nhẹ nhàng lau lên mặt, mắt và môi theo chuyển động tròn (Riêng đối với vùng mắt, bạn hãy giữ miếng bông tẩy trang trên mắt vài giây để nước tẩy trang thấm sâu và cuốn đi lớp make-up dễ dàng hơn).
 - Sử dụng để tẩy trang nhanh (không cần rửa lại với nước)', '229000'),
