('2', '1', 'COCO-S02-C01-0003', 'Sữa rửa mặt 3W Clinic Hàn Quốc mẫu mới 100ml cấp ẩm, làm sạch da loại bỏ bụi bẩn', '3W Clinic là thương hiệu mỹ phẩm nổi tiếng của Hàn Quốc, nhờ thành phần tinh xuất từ thiên nhiên lành tính nên rất được ưa chuộng trên nhiều nước trong đó có Việt Nam. Dù là chất lượng sản phẩm tuyệt vời, được sản xuất theo một quy trình nghiêm ngặt, được kiểm nghiệm một cách chặt chẽ nhưng giá cả của mỗi sản phẩm lại ở mức tầm trung. Có lẽ do vậy mà đây là ưu điểm được nhiều chị em ví von là thương hiệu bình dân luôn đồng hành cùng các chị em trên mọi nẻo đường.', '46300'),
