 ***Quà tặng đính kèm có thể xuất hiện tùy theo từng đợt nhập hàng, số lượng có hạn', '136000'),
('1', '2', 'COCO-S01-C02-0003', 'Sáp dưỡng ẩm Vaseline Mỹ 100% Pure Petroleum Jelly Original 49g, 50g, 100g - Đa Năng', 'Mô tả sáp Vaseline dưỡng môi 100% Pure Petroleum Jelly Original Mỹ
 Vaseline dưỡng môi 100% Pure Petroleum Jelly có công dụng làm mềm lớp sừng, làm lành các vết thương ngoài da do da bị khô, nẻ. Thành phần là dầu khoáng chất lấy từ trong khoáng sản tự nhiên có trong lòng đất không lẫn tạp chất… có khả năng làm mềm da hiệu quả, dùng tập trung cho những vùng khô nẻ nhiều như khuỷu tay, đầu gối, mắc cá, gót chân….
 Công dụng chính dưỡng môi vaseline 
 - sáp dưỡng ẩm vaseline có khả năng bảo vệ da khỏi những tác động từ môi trường xung quanh bằng việc tăng cường mô liên kết tế bào, bổ sung độ ẩm cho da. Từ đó sẽ ngăn ngừa tình trạng khô rát, nứt nẻ cũng như giúp vết hư tổn trên da mau phục hồi.
 - Kết cấu sáp dưỡng ẩm vaseline ở dạng sáp sẽ giúp dưỡng ẩm và duy trì độ ẩm trên các vùng da lâu hơn.
 - Làm da mềm mịn, kể cả những vùng da chai lì như khuỷu tay, đầu gối, mắt cá, gót chân.
 - Ngoài công dụng dưỡng ẩm trên da, sáp dưỡng ẩm Vaseline còn có rất nhiều công dụng đa năng khác như: giúp tẩy da chết môi, dưỡng môi, tẩy trang, bảo vệ da đầu khi nhuộm tóc, làm hight cho gò má mí mắt, bảo vệ móng, giữ mùi nước hoa, phục hồi tóc chẻ ngọn, giúp da mới xăm mau lành.
 Thành phần chính sáp nẻ vaseline 
 - Sáp dưỡng ẩm là một hỗn hợp các dầu khoáng và các loại sáp được pha trộn với nhau tạo ra một jelly chỉ tan chảy ở nhiệt độ của cơ thể.
 - Vì thành phần của pure petrolium jelly không có tạp chất và hoá chất, chỉ đơn thuần là một loại dầu khoáng chất cô dặc nên có thể dùng một ít để làm mềm những vùng da bị bong tróc trong những ngày lạnh trước khi trang điểm cũng không gây ảnh hưởng gì.
 Hướng dẫn sử dụng và bảo quản sáp dưỡng vaseline 
 - Bôi sáp dưỡng môi vaseline vào các vùng da khô rát, nứt nẻ, bong tróc trên cơ thể (từ khuôn mặt cho đến các bộ phần trên cơ thể) vào buổi tối hoặc khi nào cảm thấy da bị khô.
 - Đậy nắp kín sau khi dùng.
 - Bảo quản nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.
 Mẹo sử dụng kem nẻ vaseline 
 - Bôi sáp dưỡng ẩm vaseline lên chân vào buổi tối trước khi đi ngủ, đi tất và sáng dậy với đôi chân mềm dịu nhất
 - Bôi kem nẻ vaseline vào đầu gối, cùi chỏ để da tại đó luôn mềm mịn
 - Bôi sáp nẻ vaseline vào móng tay trước khi cắt tỉa để móng được mềm và dễ tạo hình, không bong xước
 - Bôi dưỡng môi vaseline vào những vùng da bị bong tróc trong những ngày lạnh trước khi trang điểm để làm mềm da
 - Sử dụng sáp dưỡng môi vaseline như một loại son dưỡng môi
 Thương hiệu: Vaseline
 Xuất xứ: Mỹ
 Trọng lượng: 49g/50g/100g/106g/368g
