('3', '1', 'COCO-S03-C01-0004', 'Gel Lột Mụn Than Hoạt Tính Lucky Star 60ml/200ml', 'Gel lột mụn Lucky Star than hoạt tính giúp thải độc làm sạch da, làm sạch cặn bã từ sâu bên trong chân lông, làm sạch lượng dầu thừa, hạn chế hình thành nhân mụn mới khi thường xuyên sử dụng, sản phẩm giúp sáng da và mịn da, không gây kích ứng cho da mặt, dùng được cho da nhạy cảm.
