('2', '3', 'COCO-S02-C03-0001', 'Dũa mỏng OPI - Dũa móng OPI loại mỏng chuyên dụng cho dân làm nail', 'Dũa mỏng OPI - Dũa móng OPI loại mỏng chuyên dụng cho dân làm nail
 - Dũa móng OPI loại mỏng là dụng cụ dùng dũa móng thật không thể thiếu trong hộp đồ nghề của các thợ làm nail. 
