 Hướng dẫn sử dụng dũa mỏng OPI:
  - Bước 1: Khi bắt đầu ta dũa từ phần đỉnh của móng tay trước, cầm dũa chính xác và vuông góc với móng.
  - Bước 2: Trong quá trình dũa mặt móng, ta cần giữ chiếc dũa song song với cạnh bên của móng, không để cạnh của cây dũa đi vào góc móng sẽ dễ khiến móng bị gãy.
  - Bước 3: Cuối cùng ta làm tròn các góc để tạo ra hình dáng móng mong muốn.
 Lưu ý: 
 - Bảo quản dũa mỏng OPI nơi khô ráo, thoáng mát, tránh ánh nắng mặt trời, để xa tầm tay trẻ em. 
