 - Body mist là sản phẩm kết hợp giữa sữa dưỡng thể và nước hoa. Đây là dòng sản phẩm mang tính năng 2 trong 1 vừa đem lại hương thơm cho bạn lại vừa giúp nuôi dưỡng làn da mỏng manh khỏi những kích ứng không cần thiết mà dòng nước hoa thông thường không có được.
 - Bodymist là 1 thể khác của nước hoa khi lượng tinh dầu ít hơn nhiều so với các loại nước hoa danh tiếng.Nhưng vẫn đảm bảo rằng bạn vẫn có thể thơm ngào ngạt, ngất ngây, lôi cuốn lưu hương trong khoảng thời gian dài đến 7 – 8 tiếng đồng hồ. Việc lưu giữ hương lâu còin tùy thuộc vào thời tiết & cơ thể của chính bạn nhé. Nếu xịt vào quần áo, hương sẽ lưu được lâu hơn, có khi đến cả nửa ngày. Nếu bạn nào thích điệu đà có thể xịt vào tóc khi tóc đang còn hơi ẩm, sau đó dùng máy sấy sấy lạnh thì hương thơm sẽ thoang thoảng cả ngày.
