('3', '2', 'COCO-S03-C02-0003', 'Nước Tẩy Trang Dành Cho Da Nhạy Cảm Bioderma Sensibio H20 500ml', '*Sản phẩm xuất kho đảm bảo có HSD từ 06 tháng trở lên
 "Nước Tẩy Trang Dành Cho Da Nhạy Cảm Bioderma Sensibio H20 500ml
 Nước Tẩy Trang Dành Cho Da Nhạy Cảm Bioderma Sensibio H20 là sản phẩm dạng nước có chứa các hạt micelle, tương thích hoàn hảo với làn da. Yếu tố cấu thành nên hạt micelle là các ester acid béo, tương tự như phospholipid của màng tế bào da và giúp tái tạo lớp màng hydrolipid của da một cách tự nhiên. Sản phẩm thuộc dòng Sensibio (dành cho da nhạy cảm) với đặc trưng là nắp chai màu hồng.
 Thành phần và công dụng:
 - Nước Tẩy Trang Dành Cho Da Nhạy Cảm Bioderma Sensibio H20 tẩy trang nhẹ nhàng không cần rửa lại bằng nước, làm sạch và làm dịu da
 - Chiết xuất lá cây lô hội có tác dụng làm sáng da và giữ ẩm cho da.
 - Chiết xuất từ dưa chuột có chức năng làm mềm và cung cấp dưỡng chất cho da.
 - Chiết xuất trà xanh giúp chống o.xi hóa, làm chậm quá trình lão hóa da.
 - Sodium hydroxide giúp da hấp thụ nước và độ ẩm.
 - Dung dịch nước tẩy trang trong suốt, miệng chai vừa đủ tránh được tình trạng lãng phí sản phẩm.
 - Sản phẩm ứng dụng công nghệ Micellar giúp làm sạch sâu lỗ chân lông, lớp trang điểm hằng ngày, có thể dùng để tẩy trang cả vùng mắt và môi. Đặc biệt, sau khi sử dụng sản phẩm không cần rửa lại bằng nước.
 - Dung tích 500ml siêu tiết kiệm.
 Đối tượng sử dụng:
 Nước Tẩy Trang Dành Cho Da Nhạy Cảm Bioderma Sensibio H20 thích hợp với mọi loại da, đặc biệt là da nhạy cảm.
 Hướng dẫn sử dụng:
 - Làm ướt bông tẩy trang với Sensibio H20
 - Nhẹ nhàng tẩy trang vùng mặt và mắt
 - Thực hiện lại thao tác trên cho đến khi không thấy bám bẩn trên bông tẩy trang nữa
 - Dùng khăn bông lau nhẹ da mặt"
