 Thông tin thương hiệu: 
 BIODERMA là một trong những hãng dược-mỹ phẩm đi đầu về việc tìm ra những giải pháp mới trong ngành dược-mỹ phẩm tại Pháp. Sản phẩm của Bioderma được sản xuất nghiêm ngặt dưới sự kiểm soát của các bác sĩ da liễu hàng đầu nước Pháp. Bioderma cũng là hãng tiên phong về nước tẩy trang. Đây là hãng đầu tiên đem tới giải pháp micellaire: sử dụng các hoạt chất tẩy rửa siêu nhỏ (hạt micelle) để lấy đi các bụi bẩn, tế bào chết, mỹ phẩm trên da, mà không cần dùng tới các chất tẩy rửa hay được sử dụng như chất xút (xà phòng) hoặc các chất tẩy rửa thuộc nhóm sulfates..
