('3', '6', 'COCO-S03-C06-0001', '(Bán Buôn – Sỉ) Nước Hoa Body Mist Shimang Trà Thơ Mẫu Mới Nắp Gỗ Thân Thủy Tinh Vỏ Mờ Sang Trọng Nh8 Xịt Thơm Body Mist', '- Dung Tích:50ml.
