 - Orange Girl: Một sự hòa quyện của các tầng hương thơm ngọt mát sắc cam chanh, tạo cảm giác ngơ ngẩn của 1 nàng thơ, hương đầu là hương chanh, cam Bergamot, quýt, kết hợp với hạt beancurd nhật bản, hương giữa là cỏ xạ hương thyme giúp nước hoa thêm phần sang trọng
 - Cheese Peach: Mùi hương tươi mới như 1 thiếu nữ tuổi 17, khiến ai cũng muốn lại gần và bảo vệ. Hương đầu là hương nhài và táo, hương giữa là mật ong, đào kết hợp với hoa hồng, hoa phong lữ - một mùi hương khó tả giữa hương phấn mát, lẫn mùi của múi quất nhẹ, thoảng có mùi hoa hồng, và sau cùng là mùi dâu tây chưa chín mọng, hương cuối là gỗ đàn hương và xạ hương, 1 sự kết thúc vô cùng quyến rũ
 - Monet Garden: 1 mùi hương rất mới của Shimang, mang lại cảm giác xanh mát vào mùa hạ , không phải kiểu xanh mát từ cây cỏ mà là cảm giác thư thái trong lành và rất dễ chịu. Hương đầu là sự kết hợp từ hương hoa sen, dưa hấu, hoa chi tiên và lan nam phi, hương giữa là hoa cẩm chướng, hoa Ly và hoa mẫu đơn, hương cuối là hoa nhài nở ban tối, xạ hương và gỗ đàn hương. Một mùi hương vô cùng cầu kỳ, vừa sang trọng lại vừa ấm áp, gần gũi tạo cho người đối diện cảm giác vô cùng dễ chịu
 - White Tea: Một mùi hương lãng du, như mây như gió, êm dịu vừa xa xôi lại vừa gần gũi, hương đầu là sự kết hợp của lá trà, chanh, hoa cam Neroli, hương giữa là hạt đậu khấu kết hợp 1 chút tiêu mang lại 1 mùi vị rất unisex, hương cuối là mùi xạ hương hổ phách, kết hợp vị gỗ nồng ấm, đây là 1 mùi hương rất cá tính unisex phù hợp cho cả nam và nữa đó ạ
 - Jasmine Pear: một mùi hương ngọt ngào như mật ong, tạo cảm giác dễ chịu vô tư chìm đắm trong hương thơm đó, quên hết mọi buồn phiền, các tầng hương gồm hương chanh mật ong, đến hoa mẫu đơn, nước hoa hồng và gỗ đàn hương và hương hoa violet
 - Forrest Letter: mùi hương gỗ trà trong đêm tuyết, một mùi hương rất ấn tượng của bst mới này, hương đầu là: hương chanh cam, hương giữa mùi chủ đạo là mùi lá trà, hoa nhài, kết hương là mùi cỏ hương bài và hương thuốc lá. Ngay từ những giây phút ban đầu, mùi hương ngọt ngào như những viên kẹo dẻo vị trái cây tươi ngon đầy hấp dẫn sẽ chào đón bạn. Kéo theo là mùi hương của những điếu thuốc lá tuy già cỗi nhưng vẫn rất sang trọng
 - Rainbow Beat: Mùi hương ngọt ngào từ trái cây và hương hoa, 1 mùi hương rất tươi trẻ, mở đầu là hương bưởi đào và tiêu hồng, tiếp theo là hương hoa mâm xôi', '40000'),
('2', '2', 'COCO-S02-C02-0004', 'Dầu Tẩy Trang Sạch Sâu Dưỡng Ẩm Tối Ưu Hada Labo Advanced Nourish 200ml', '*Sản phẩm xuất kho đảm bảo có HSD từ 06 tháng trở lên
 "Dầu Tẩy Trang Sạch Sâu Dưỡng Ẩm Tối Ưu Hada Labo Advanced Nourish 200ml
 Dầu tẩy trang Hada Labo Advanced Nourish với dầu Ô liu tinh khiết kết hợp cùng HA và SHA nhẹ nhàng làm sạch hiệu quả lớp trang điểm (kể cả mascara không trôi), giữ da luôn ẩm mượt và sáng mịn. Đồng thời, cơ chế làm sạch sâu Deep Purifying hoàn toàn lấy đi bụi bẩn, bã nhờn và cặn trang điểm, giúp giảm mụn đầu đen và thu nhỏ lỗ chân lông.
 Thành Phần Chính và Công Dụng:
 - Dầu Ô liu tinh khiết (Pure Olive Extract): Làm sạch sâu từ trong lỗ chân lông nhưng vẫn dịu nhẹ với làn da, không gây căng khô sau khi sử dụng.
 - HA, SHA: Nhẹ nhàng thấm sâu và giữ nước lâu hơn, tạo màng dưỡng ẩm bảo vệ da.
 - Dầu tẩy trang làm sạch bụi bẩn, cặn trang điểm.
 - Dưỡng da ẩm mượt, sáng mịn, tươi trẻ mỗi ngày.
 Hướng Dẫn Sử Dụng:
 Bước 1: Giữ tay và mặt khô, lấy một lượng dầu tẩy trang vừa đủ vào lòng bàn tay, thoa đều lên toàn bộ mặt.
 Bước 2: Massage nhẹ nhàng theo chuyển động tròn giúp dầu dễ dàng hòa tan và lấy đi bụi bẩn, bã nhờn, cặn trang điểm và mascara không trôi.
 Bước 3: Vỗ nhẹ nước lên mặt, tiếp tục massage đều đến khi dầu chuyển hóa thành sữa.
 Bước 4: Rửa sạch mặt với nước hoặc nước ấm.Nên dùng kết hợp với Kem rửa mặt Hada Labo ADVANCED NOURISH để đạt hiệu quả tối ưu.
 Hướng dẫn sử dụng
 Bước 1: Lấy một lượng dầu tẩy trang vừa đủ thoa đều lên mặt. 
 Bước 2: Massage nhẹ theo chuyển động tròn để lấy đi bụi bẩn, bã nhờn, cặn trang điểm. 
 Bước 3: Vỗ nhẹ nước lên mặt và massage đến khi dầu chuyển thành sữa. 
 Bước 4: Rửa sạch mặt với nước" 
