 Thông tin thương hiệu: Hada Labo là sự kết hợp giữa chữ Hada – da và Labo – nghiên cứu. Đây là dòng mỹ phẩm ra đời trong phòng nghiên cứu của công ty chế dược Rohto Nhật Bản với bề dày hơn 30 năm kinh nghiệm nghiên cứu về da. Dựa trên những kinh nghiệm được xây dựng và tích lũy trong thời gian dài, với phương châm “Đơn giản và Hoàn hảo”, Hada Labo đã cho ra đời những sản phẩm chăm sóc da giúp mang vẻ đẹp trở về với giá trị đích thực của nó: đơn giản, hoàn hảo và tự tin. Dòng sản phẩm Hada Labo loại bỏ tối đa các thành phần có thể gây hại cho da như: hương liệu, chất tạo màu, dầu khoáng… Hada Labo chỉ tập trung khai thác dưỡng chất mang lại hiệu quả trực tiếp cho làn da, để mỗi sản phẩm có độ tinh khiết cao nhất, cho hiệu quả tối ưu.
