('2', '3', 'COCO-S02-C03-0002', 'Keo 401 dán móng nail (20g) - Keo dán đa năng Hàn Quốc loại tốt chuyên dụng cho dân làm móng', 'Keo 401 dán móng nail siêu chắc, gắn đá siêu bền (20g) - keo dán đa năng Hàn Quốc loại tốt chuyên dụng cho dân làm móng
 - Keo 401 là một dụng cụ trong bộ làm móng chuyên nghiệp dùng trong việc gắn kết móng giả với móng thật hoặc gắn đá trang trí loại nhỏ và vừa.
 - Keo 401 được thiết kế với dáng lọ nhỏ gọn thuận tiện cho quá trình sử dụng, di chuyển và cất giữ. Sản phẩm gồm 2 bộ phận chính là nắp đậy và thân lọ chứa dung dịch keo. Thân lọ được làm bằng nhựa cứng giúp bảo vệ phần keo bên trong dưới tác động của môi trường bên ngoài, có đầu nhỏ từng giọt keo giúp thợ nail có thể dễ dàng điều chỉnh lượng keo tránh lãng phí keo. Phần nắp đậy chắc chắn.
 Thông tin sản phẩm: 
  + Chất liệu: nhựa
  + Dung dịch: dạng keo lỏng, không màu nên không ảnh hưởng đến thẩm mỹ móng
  + Đặc điểm: Cực kì nhanh khô, có mùi nhẹ, độ kết dính cao.
  + Quy cách đóng gói: lẻ 1 chai
 - Hướng dẫn sử dụng keo 401: 
  + Bước 1: Vệ sinh, cắt dũa nhặt da móng thật. Mài nhám bề mặt móng thật để tăng độ liên kết. 
  + Bước 2: Chọn size móng giả phù hợp với móng thật. Chải keo 401 một lượng vừa đủ lên bề mặt móng thật. Dùng tay gắn chặt móng giả với móng thật. 
  + Bước 3: Sơn màu, trang trí để hoàn thiện móng cho khách. 
 - Lưu ý:
  + Bảo quản sản phẩm trong hộp, tủ đựng dụng cụ, tránh va đập mạnh, đóng nắp chai kĩ sau khi sử dụng.
  + Để xa tầm tay trẻ em. 
  + Tránh tiếp xúc trực tiếp với da.
 - Cam kết khi mua hàng tại shop:
  + Shop luôn mang đến cho khách hàng những sản phẩm chính hãng, bảo đảm đúng chất lượng. 
  + Hình ảnh sản phẩm do nhân viên shop tự chụp 100%.
  + Mọi thắc mắc của khách yêu về đơn hàng luôn được giải đáp nhanh chóng bởi đội chăm sóc khách hàng của shop.
