('3', '2', 'COCO-S03-C02-0005', 'Kem che khuyết điểm ZEESEA che phủ toàn diện hiệu quả lâu trôi 3g', 'Thời gian giao hàng dự kiến cho sản phẩm này là từ 7-9 ngày
 Kem che khuyết điểm hiệu quả ✔ Làm sáng màu da ✔ 
 Kem nền ✔ Kết cấu nhẹ ✔ Di động ✔
 1. Che giấu khuyết điểm - Để giúp che đi vết thâm quầng mắt và các khuyết điểm khác. Bạn biết rằng làn da sạch sẽ, không tuổi là nền tảng của vẻ ngoài tuyệt vời và sự xuất hiện của lỗ chân lông, che đi các khuyết điểm và có được làn da trông tự nhiên. 
 2. Kem che khuyết điểm mang lại độ sáng bóng tức thì cho bóng dưới mắt tối và điều chỉnh các khuyết điểm. Các vùng da săn chắc, nhạy cảm được làm mịn và đồng đều rõ rệt.
 3. Làm sáng vùng chữ T
 Giúp làm sáng vùng chữ T và vùng dưới mắt.
 4. Làm kem lót môi
 Làm sáng các đường viền môi và tạo lớp trang điểm môi đẹp.
 Một phần các bước che khuyết điểm:
 Khuyết điểm màu sáng: kem nền đầu tiên → sau đó kem che khuyết điểm
 Khuyết điểm màu tối: kem che khuyết điểm đầu tiên → sau đó đánh phấn nền → che khuyết điểm lại
 Thương hiệu: ZEESEA
 Dung tích: 3ml
 Loại da sử dụng phù hợp: Mọi loại da
 Xuất xứ: Được sản xuất tại Trung Quốc
 Hiệu quả: Kem che khuyết điểm 
 Tiêu chuẩn mỹ phẩm: Thông thường
 Mỹ phẩm chuyên dụng: Không
 Thời hạn sử dụng mỹ phẩm: 36 tháng', '69000'),
