 Lastes last at least 5 days and is reusable. Durable using acrylic transfer technology.
 2. *Note:
 ***Please allow for a 0.05 cm error due to manual measurement.
 ***Also, colors may vary slightly due to different screen resolutions. We appreciate your understanding.
 ***If your nails are larger than others, you can choose longer false nails from our store.
 3. *Instructions for Use:
 1) Trim the sides and skin-toned areas of your nails to ensure a perfect fit with the nail polish stick;
 2) Clean your nails with acetone-based nail polish remover to remove all nail polish;
 3) Choose the appropriate size of false nails for each finger;
 4) Apply glue to the false nails;
 5) Apply a thin layer of glue to your natural nails;
 6) Starting from the skin-toned area, press and hold for 5 seconds;
 7) Trim and buff the new nail shape if necessary.
 4. *Removal Tips:
 Soak your nails in warm water for 2 minutes to easily remove the false nail glue.
 Do not tear forcefully to avoid damaging the nail surface.
