('1', '5', 'COCO-S01-C05-0005', 'Bóng Gai Dãn Cơ Massage Giảm Mệt Mỏi, Phục Hồi Cơ Bắp Sau Luyện Tập', 'Sản phẩm: Bóng Gai Massage - Spike Ball
 1. THÔNG SỐ SẢN PHẨM:
 Mã sản phẩm: bonggai
 Chất liệu: Nhựa PVC
 Màu sắc: Đen, Xám, Xanh biển, Tím, Hồng, Cam
 Kích thước: Đường kính 7.5cm
 Trọng lượng: 50g
 Xuất xứ: Trung Quốc
 Tình trạng: Mới
