('1', '2', 'COCO-S01-C02-0006', 'Bigsize - Nước tẩy trang bí đao Cocoon tẩy sạch makeup & giảm dầu 500ml', 'Làn da dầu và mụn rất nhạy cảm nên cần được thiết kế một loại nước tẩy trang phù hợp. Với công nghệ micellar và NatraGem™ S150, Nước Tẩy Trang Bí Đao giúp làm sạch hiệu quả lớp trang điểm, bụi bẩn và dầu thừa, mang lại làn da sạch hoàn toàn và mềm mịn.
 LÝ TƯỞNG CHO:
 • Làn da cần tẩy sạch nhanh lớp trang điểm
 • Da dầu, mụn thường xuyên trang điểm cần một sản phẩm tẩy trang phù hợp
 CÔNG DỤNG:
 - Làm sạch bụi bẩn và lớp trang điểm trên bề mặt da
 - Giảm mụn và giảm dầu.
 THÀNH PHẦN CHÍNH:
 • Chiết xuất bí đao: Có đặc tính làm mát, làm giảm nhiệt và giúp giảm mụn trứng cá, mụn viêm.
 • Rau má: Các hợp chất sinh học như axit asiatic, asiaticoside, axit madecassic và madecassoside có trong rau má là những chất chính giúp làm dịu da.
 • Tinh dầu tràm trà: Loại tinh dầu có mùi thơm ấm áp, cay nồng giúp giảm mụn trứng cá, mụn viêm.
 • NatraGem™ S150: Gồm tổ hợp chất Polyglyceryl-4 Laurate/Sebacate và Polyglyceryl-4 Caprylate/Caprate, sở hữu những ưu điểm vượt trội: có nguồn gốc 100% từ thực vật, được chứng nhận hữu cơ bởi Ecocert; có khả năng hòa tan mạnh những chất ưa dầu có trong các sản phẩm trang điểm, vì thế giúp làm sạch mạnh mẽ và cuốn trôi nhanh chóng lớp makeup, bã nhờn và bụi bẩn trên da. Khi so sánh với các chất làm sạch khác, tổ hợp chất này đã được chứng minh hạn chế gây mất nước qua da và rất an toàn trên làn da thông qua các bài test in-Vivo.
 • O-Cymen-5-Ol và Cetylpyridinium chloride: Giúp làm giảm mụn.
 • Betaine: Là hoạt chất dưỡng ẩm được chiết xuất từ củ cải đường, giúp hỗ trợ bảo vệ da trước căng thẳng từ môi trường bên ngoài như ô nhiễm môi trường, khói bụi.
 THÀNH PHẦN ĐẦY ĐỦ:
 AQUA/WATER, POLYGLYCERYL-4 LAURATE/SEBACATE, POLYGLYCERYL-4 CAPRYLATE/CAPRATE, BETAINE, BENINCASA CERIFERA FRUIT EXTRACT, CENTELLA ASIATICA EXTRACT, O-CYMEN-5-OL, PROPANEDIOL, GLYCERETH-26, GLYCERIN, TRISODIUM ETHYLENEDIAMINE DISUCCINATE, SODIUM LACTATE, CETYLPYRIDINIUM CHLORIDE, HYDROXYACETOPHENONE, BUTYLENE GLYCOL, MELALEUCA ALTERNIFOLIA LEAF OIL, LACTIC ACID, POTASSIUM SORBATE.
 HƯỚNG DẪN SỬ DỤNG:
 Thấm đều sản phẩm lên bông tẩy trang, nhẹ nhàng lau khắp mặt để làm sạch lớp trang điểm và bụi bẩn. Dịu nhẹ cho vùng môi và mắt.
 • Lưu ý: Chỉ dùng ngoài da.
 • Hướng dẫn bảo quản: Đóng kín nắp sau khi sử dụng. Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp và nhiệt độ cao.
 CAM KẾT:
 • Không cồn ethanol
 • Không sulfate
 • Không dầu khoáng
 • Không paraben
 • Không thử nghiệm trên động vật
 Xuất xứ: Việt Nam
 Dung tích: 500ml
 Hạn sử dụng: 3 năm kể từ NSX', '274000'),
('2', '3', 'COCO-S02-C03-0003', 'Giấy lau gel nail , giấy chùi gel', 'Giấy lau gel nail, giấy chùi gel
 * Mô tả sản phẩm:
 - Giấy lau gel nail còn được gọi là giấy chùi gel, được sử dụng để vệ sinh móng, kết hợp với nước rửa móng tay axeton để làm sạch móng
 - Dùng để lau gel, lau bụi bẩn, vệ sinh bề mặt trong quá trình làm móng...
 - Giấy lau dày, độ mịn vừa phải không bị xơ, sổ lông và không bám bụi
 - Giấy lau có tác dụng lau chùi, vệ sinh bề mặt trong quá trình làm móng cho chuyên dụng ngành nail
 - Màu sắc: Trắng
 * Cách sử dụng
 - B1: Tách giấy thành từng tờ để sử dụng
 - B2: Dùng sau khi đắp gel để lau đi lớp gel thừa trên bề mặt của móng...
 * Lưu ý:
 - Không nên tái sử dụng giấy lau làm giảm tác dụng của giấy
 - Bảo quản nơi khô ráo, thoáng mát
 - Tránh sản phẩm gần lửa, nguồn nhiệt cao
 * Chính sách đổi trả:
 1. Chính sách đổi trả tất cả các sản phẩm (Kể cả đã bóc ra sử dụng)
 - Shop khuyến khích khách hàng kiểm tra hàng hóa ngay khi nhận hàng về tay và phản hồi lại với chúng tôi trong vòng 10 ngày.
 - Đổi trả thoải mái trong 10 ngày (kể từ lúc khách nhận được hàng). Không cần biết lí do, chỉ cần khách hàng không thích là được hỗ trợ đổi/ trả lại hàng, hoàn tiền 100%. Trường hợp sản phẩm không bị lỗi, khách vui lòng trả ship.
 2. Chính sách bảo hành theo sản phẩm lỗi
 - Đối với sản phẩm điện tử: Bảo hành đổi mới trong vòng 5 tháng kể từ ngày nhận hàng.
 - Bảo hành đổi mới trong vòng 1 tháng kể từ ngày nhận hàng, 4 tháng tiếp theo nếu lỗi công ty hỗ trợ đổi sửa chữa, nếu không sửa chưa được công ty hỗ trợ 30% giá trị máy ở thời điểm hiện tại.
 - Đối với sản phẩm dung dịch: Bảo hành đổi mới trong vòng 1 tháng kể từ ngày nhận hàng.
 - Đối với sản phẩm còn lại: Bảo hành đổi mới trong vòng 10 ngày kể từ ngày nhận hàng.
 3. Phí giao hàng: Miễn phí hoàn toàn phí ship đổi trả 2 chiều trong 10 ngày đầu nếu sản phẩm có lỗi.
