 + Khả năng lưu hương cực lâu, 3-4h /người, thơm ngay cả sau khi tắm
 Mùi thơm nước hoa Karri ngọt ngào sang trọng, phù hợp đi làm đi học đi chơi đều được.
 Vị trí xịt nước hoa lý tưởng cho nữ
 Những vị trí xịt nước hoa lý tưởng theo các chuyên gia khuyên là: bên trong khuỷu tay, gáy, sau tai, cổ tay, sau đầu gối. Cách xịt nước hoa lên những vị trí có mạch đập, tỏa nhiệt giúp mỗi cử động của bạn đều khiến mùi hương lan tỏa tự nhiên. Bạn cũng có thể xịt một ít lên ngực, vào lòng bàn tay rồi vuốt nhẹ lên tóc và một chút sau lưng nếu muốn, để dù đứng ở phương hướng nào người khác cũng có thể cảm nhận được mùi hương của bạn', '39000'),
('1', '3', 'COCO-S01-C03-0004', 'Base Top Vinimay, Cứng móng, Kiềm dầu, Top giọt sương, Top lì, Top loang, Top Cường Lực, Top Kim Cương, Phá Gel Vinimay', 'CHI TIẾT SẢN PHẨM :
 1- Base liên kết: liên kết móng và lớp sơn chắc hơn
 2- Top bóng: bề mặt phủ bảo vệ và tạo độ bóng cho bề mạt sơn
 3- Cứng móng: Hỗ trợ móng yếu, giòn, gấy do tiếp xúc nhiều với hóa chất, mài giũa, sử dụng sau khi hơ khô lớp base
 4- Kiềm dầu: loại bỏ bụi bẩn, lớp dầu mồ hôi bám trên bề mặt móng và xung quanh viền
 5- Top giọt sương: tạo giọt sương trang trí cho móng
 6- Top lì: bề mặt phủ bảo vệ tạo độ lì cho sơn, đối lập với top bóng
 7- Top loang: tạo loang vân đá, gỗ, khói, hoa...
 8- Top kim cương: sản phẩm chuyên dụng để làm cứng bề mặt móng, bảo vệ móng.
 Base đa năng: 
 - Khử dầu (kiềm dầu) thay thế Primer: Phù hợp cho tất cả móng nhiều dầu
 - Base cứng móng: Giúp chắc khỏe cho cả những loại móng yếu, dễ gãy.
 - Liên kết sơn gel: Lớp nền liên kết các bước sơn gel hiệu quả.
 - Liên kết gel đắp (Bonder): Liên kết gel và bột đắp móng một cách bền chắc.
 - Nối móng: Sử dụng như một loại gel úp hoặc nối móng.
 Khách hàng lưu ý: Sản phẩm là hàng loại tốt
 Bảo quản:
 - Tránh ánh sáng đèn ,mặt trời 
 - Để xa tầm tay trẻ em và thú nuôi.
 - Không để nước và các chất khác lẫn vào làm hỏng Gel
 - Đọc kỹ hướng dẫn trước khi khi sử dụng.
 *Cửa hàng cam kết : 
 - Phản hồi lại khách hàng nhanh chóng kịp thời trong vòng 24h
 - Khách hàng có thể đổi trả sản phẩm trong vòng 3 ngày với điều kiện hàng hóa còn nguyên tem mác
 - Phản ánh lại cho shop mọi vấn đề trước khi đánh giá sao. Khách hàng đánh giá 5 sao sẽ được nhận nhiều ưu đãi cho đơn hàng tiếp theo
 - Bao bì sản phẩm sẽ cập nhật theo từng đợt sản phẩm
 * Bảo quản
 - Bảo quản nơi khô ráo, thoáng khí,tránh. sản phẩm gần nguồn nhiệt và tiếp xúc trực với ánh sáng.
 - Đậy nắp kỹ khi không sử dụng hoặc đã dùng xong !
