('2', '2', 'COCO-S02-C02-0007', 'Khăn lau mặt dùng 1 lần spa 50/80 khăn LIKADO kích thước (20x20cm)', '𝐊𝐇𝐀̆𝐍 𝐋𝐀𝐔 𝐌𝐀̣̆𝐓 𝟏 𝐋𝐀̂̀𝐍 𝐋𝐈𝐊𝐀𝐃𝐎 𝐂𝐔𝐎̣̂𝐍 𝐓𝐑𝐎̀𝐍 𝟓𝟎 𝐓𝐎̛
