('3', '2', 'COCO-S03-C02-0007', '[ĐỘC QUYỀN HASAKI - MUA 1 TẶNG 2 - QUÀ GIỚI HẠN] Garnier Micellar Cleansing Water 400ml Hasaki Sản Phẩm Chính Hãng', 'Nước Làm Sạch Và Tẩy Trang Cho Mọi Loại Da Garnier Micellar Cleansing Water 400ml hiện đã có mặt tại Hasaki với 4 phân loại dành cho từng vấn đề da riêng biệt:
 Lưu ý: Hiện Hasaki đang bán song song cả 2 mẫu cũ và mới.
 1. Nước Tẩy Trang Garnier Skin Naturals Micellar Oil-Infused Cleansing Water
 Sản phẩm ứng dụng công nghệ Micelles kết hợp cùng dầu Argan giúp làm sạch sâu và loại bỏ toàn bộ lớp trang điểm, kể cả lớp trang điểm không thấm nước cứng đầu nhất. Công thức độc đáo dễ dàng thẩm thấu, giúp nuôi dưỡng làn da mềm mại và ẩm mịn sau khi tẩy trang mà không để lại cảm giác nhờn dính.
 Loại da phù hợp:
 - Sản phẩm phù hợp cho mọi loại da, đặc biệt là da khô.
 Giải pháp cho tình trạng da:
 - Da thiếu ẩm - thiếu nước, dễ khô căng, thô ráp sau khi tẩy trang.
 - Da trang điểm, đặc biệt là sản phẩm trang điểm lâu trôi, chống thấm nước.
 2. Nước Tẩy Trang Garnier Skin Naturals Micellar Cleansing Water Vitamin C
 Lần đầu tiên, thương hiệu Garnier cho ra đời dòng sản phẩm nước tẩy trang mới với sự kết hợp giữa công nghệ Micelles (Micellar Technology) và thành phần làm sáng da Vitamin C - Garnier Vitamin C Micellar Water giúp loại bỏ lớp trang điểm và làm sạch da chỉ trong 1 lần sử dụng, mang lại làn da tươi sáng và rạng rỡ hơn tức thì.
 Loại da phù hợp:
 - Sản phẩm phù hợp cho mọi loại da, kể cả da nhạy cảm.
 Giải pháp cho tình trạng da:
 - Da xỉn màu & thâm sạm
 3. Nước Tẩy Trang Garnier Skin Naturals Salicilyc BHA Cleansing Water
 Là dòng sản phẩm nước làm sạch và tẩy trang đa năng được thiết kế chuyên biệt dành cho da dầu & mụn, giúp làm sạch hiệu quả mà không gây kích ứng hay tổn thương cho làn da của bạn. Với công dụng chăm sóc da 3 trong 1, bạn có thể sử dụng Garnier Micellar Water như một sản phẩm làm sạch da, toner hoặc tẩy trang. Sản phẩm dùng được cho da mặt, mắt & môi.
 Loại da phù hợp:
 - Sản phẩm phù hợp cho da dầu, hỗn hợp thiên dầu.
 Giải pháp cho tình trạng da:
 - Da dầu thừa - lỗ chân lông to
 - Da mụn hoặc dễ nổi mụn
 4. Nước Tẩy Trang Garnier Micellar Cleansing Water For Sensitive Skin 400ml
 Là dòng sản phẩm nước làm sạch và tẩy trang đa năng được thiết kế chuyên biệt dành cho làn da nhạy cảm, giúp làm sạch hiệu quả mà không gây tổn hại cho làn da của bạn. Sản phẩm chăm sóc da 3 trong 1 này có thể được sử dụng như một sản phẩm làm sạch, toner hoặc tẩy trang - với công nghệ Micelles chứa các hạt phân tử mi-xen giúp loại bỏ bụi bẩn, dầu thừa và lớp trang điểm theo cơ chế hoạt động của nam châm mà không cần chà xát mạnh, không cần rửa lại với nước. Công thức không chứa cồn & hương liệu, không gây dị ứng, thích hợp cho da nhạy cảm.
 Loại da phù hợp:
 - Sản phẩm phù hợp cho da nhạy cảm.
 Giải pháp cho tình trạng da:
 - Da nhạy cảm - kích ứng
 Thông số sản phẩm:
 Dung tích: 400ml
 Ngày sản xuất: Xem trên bao bì
 Hạn sử dụng: 3 năm kể từ ngày sản xuất', '140000'),
('2', '6', 'COCO-S02-C06-0003', 'body mist Xịt Thơm Toàn thân Victoria''s Secret Body Mist 236ml Siêu Thơm Cá Tính, Năng Động', 'Xịt thơm body mist, Xịt Thơm toàn thân body mist 236ml Siêu Thơm
