('3', '6', 'COCO-S03-C06-0003', 'Nước hoa Nữ KARRI Perfume Collection 30ML Màu hồng chân dài cô gái, thơm lâu, dầu thơm, nước hoa lưu hương NH02', 'Nước hoa Nữ KARRI Perfume Collection 30ML nước hoa chân dài cô gái NH02
 Dung tích (ml): 30 ml (gram).
 Loại nước hoa: EDP (Eau De Perfume).
 Nhãn hiệu: KARRI COLLECTION
 Dạng sản phẩm: Dạng xịt.
 CHI TIẾT SẢN PHẨM
 Karri là một loại nước hoa nữ được thiết kế phá vỡ mọi khuôn khổ từ trước đến nay, cung cấp một cái gì đó mới và hiện đại, đồng thời mạnh mẽ và thanh lịch.
 Karri Perfume Collection nước hoa nữ đã mang đến những nét hương đầy mạnh mẽ, hiện đại nhưng cũng không kém phần thanh lịch và duyên dáng. Mùi hương này được xem như là biểu tượng cho những người phụ nữ bản lĩnh, quyền lực, có sự nghiệp, đam mê và biết tận hưởng cuộc sống.
 Mùi hương chủ đạo của Karri là sự ngọt ngào từ mật ong, hương thơm mang lại sự nữ tính, quyến rũ, gợi cảm và dễ làm người ta say đắm. Ngoài ra thì sự thơm mát từ cam chanh cùng hương hoa cũng mang lại cảm giác dễ chịu và thoải mái. Karri là dòng nước hoa chắc chắn sẽ mang lại một mùi hương đẹp - độc - lạ xứng đáng có trong bộ sưu tập của các quý cô.
 Karri Perfume Collection với thiết kế kiểu chai mới được làm bằng thủy tinh trong suốt, còn nắp chai được thiết kế theo hình dáng điêu khắc của đôi chân phái nữ với sự khắc họa bằng màu vàng nổi bật đã tạo 1 độc đáo mới lạ từ trước đến nay.
 Vị trí xịt nước hoa lý tưởng cho nữ
 Những vị trí xịt nước hoa lý tưởng theo các chuyên gia khuyên là: bên trong khuỷu tay, gáy, sau tai, cổ tay, sau đầu gối. Cách xịt nước hoa lên những vị trí có mạch đập, tỏa nhiệt giúp mỗi cử động của bạn đều khiến mùi hương lan tỏa tự nhiên. Bạn cũng có thể xịt một ít lên ngực, vào lòng bàn tay rồi vuốt nhẹ lên tóc và một chút sau lưng nếu muốn, để dù đứng ở phương hướng nào người khác cũng có thể cảm nhận được mùi hương của bạn.
