('3', '2', 'COCO-S03-C02-0008', 'Nước Tẩy Trang làm sạch sâu dịu nhẹ cho mọi loại da - Garnier Micellar Cleansing Water 400ml', '• VÌ SAO BẠN SẼ THÍCH?
 Nước làm sạch và tẩy trang dành cho mọi loại da Garnier Micellar Water 400ml , bạn có thể chọn phân loại phù hợp với da bạn
 - [MỚI]: Dành cho da sần sùi (nắp xanh lá): Tiên phong kết hợp hoạt chất 1% [PHA, AHA] nhẹ nhàng làm sạch tế bào da chết, thúc đẩy quá trình tái tạo da, giúp da trông sáng hơn & láng mịn
 - Dành cho da dầu mụn: chứa BHA nhẹ nhàng làm sach da, lấy đi bụi bẩn, cặn trang điểm và dầu thừa gây ra tình trạng mụn. Phù hợp cho da dầu & da hỗn hợp. Lấy đi dầu thừa mà không gây khô da.
 - Dành cho da khô & trang điểm: Không chứa cồn, không gây kích ứng da. Kết cấu không nhờn, không bết dính, phù hợp với mọi loại da. Kết hợp Dầu hạt Argan thiên nhiên có tác dụng dưỡng ẩm cho da. Phân tử Micelles lấy đi bụi bẩn sâu bên trong lỗ chân lông theo cơ chế hoạt động của nam châm, dầu hạt Argan lấy đi cặn bẩn trang điểm và dưỡng ẩm da.
 - Dành cho da nhạy cảm: nhẹ nhàng làm sach da, lấy đi bụi bẩn, cặn trang điểm và làm da tươi mát. Công thức lành tính, đặc biệt an toàn trên da nhạy cảm. Đặc biệt an toàn trên da nhạy cảm. Không có cồn & hương liệu. Làm sạch và chăm sóc da dịu nhẹ.
 - Dành cho da sạm màu: làm sạch sâu và dưỡng sáng da với thành phần Vitamin C & chiết xuất quả Yuzu trong thiên nhiên. Kết hợp Vitamin C có tác dụng dưỡng sáng các vùng da xỉn màu. Kết cấu không nhờn, không bết dính, phù hợp với mọi loại da.
 • ƯU ĐIỂM NỔI BẬT
 Sử dụng công nghệ Micelles (Micellar Technology), phân tử Micelles lấy đi bụi bẩn sâu bên trong lỗ chân lông theo cơ chế hoạt động của nam châm.
 • HIỆU QUẢ SỬ DỤNG
 Màu xanh lá: Hiệu quả được kiểm chứng bởi chuyên gia:
 +20% lỗ chân lông được cải thiện*
 +32% độ mịn màng của da*
 (*Hiệu quả được đánh giá trên 85 phụ nữ, sử dụng 2 lần/ngày, sau 56 ngày, khuyến khích dùng kèm sản phẩm có SFP30)
 - Màu xanh dương: Làn da sạch thoáng, không còn dầu thừa và giảm bớt nguy cơ gây mụn
 - Màu hồng: làm sạch và chăm sóc da dịu nhẹ. Sản phẩm không cồn, không hương liệu & không paraben. Glycerin thực vật, cung cấp độ ẩm và làm dịu da. Phù hợp cho da nhạy cảm
 [MỚI] Nay đã có size khổng lồ tiết kiệm hơn
 - Màu trắng: Làn da được làm sạch sâu kể cả lớp trang điểm lâu trôi. Da được dưỡng ẩm dịu nhẹ với dầu argan.
 - Màu vàng: Ngay lập tức, làn da sạch thoáng , mềm mại và sáng rạng rỡ. Sử dụng thường xuyên giúp lấy đi lớp da chết gây ra da bị xỉn màu.
 • HƯỚNG DẪN SỬ DỤNG
 - Lắc đều, thấm một lượng vừa đủ ra bông tẩy trang
 - Lau nhẹ trên da mặt, vùng da quanh mắt và môi theo hướng xoay tròn (không chà xát da), không cần rửa lại với nước.
 - Nên dùng hằng ngày ngay cả khi không trang điểm.
 - Liều lượng: 1 lần sử dụng = 2ml
 • THÔNG TIN THƯƠNG HIỆU
 Garnier là thương hiệu làm đẹp khoa học thiên nhiên, chuyên sâu về chăm sóc và bảo vệ sức khỏe làn da. Là sự hòa quyện giữa từ hơn 90% chiết xuất nguyên liệu từ thiên nhiên và công nghệ khoa học – Green Sciences, được kiểm nghiệm bởi chuyên gia da liễu, Garnier cung cấp những giải pháp có hiệu quả đã được chứng minh hoàn toàn lành tính & an toàn, chăm sóc da của bạn khỏe đẹp từ bên trong.
 Tất cả các sản phẩm của Garnier, thông qua quá trình sản xuất thân thiện với môi trường, truyền cảm hứng cho người sử dụng về lối sống “xanh”, giải pháp dưỡng da “xanh”, kết nối con người với thiên nhiên và môi trường.
 Garnier nói “KHÔNG” với thử nghiệm trên động vật. Garnier cam kết ngưng sử dụng nhựa nguyên sinh từ năm 2025.', '127000'),
