 • ƯU ĐIỂM NỔI BẬT
 Deep Cleasing - Sạch sâu (Hồng): Có hai lớp chất lỏng giúp hòa tan chất bẩn và loại bỏ toàn bộ lớp trang điểm hiệu quả, kể cả lớp trang điểm lâu trôi và không thấm nước chỉ trong một bước. Lớp Micellar chứa các hạt mixen siêu nhỏ để len lỏi sâu và dễ dàng lấy đi bụi bẩn, dầu thừa, lớp trang điểm và chất bẩn khác mà không làm khô da. Thích hợp cho mọi loại da, kể cả da nhạy cảm.
 • HIỆU QUẢ SỬ DỤNG
 giúp làm sạch lấy đi sạch cặn trang điểm những vẫn giúp da giữ ẩm, thông thoáng và mềm mượt chỉ trong một bước.
 • HƯỚNG DẪN SỬ DỤNG
 - Lắc đều. 
 - Cho sản phẩm vào bông tẩy trang rồi nhẹ nhàng lau lên mặt, mắt và môi theo chuyển động tròn.
 - Không cần rửa lại với nước.
