('3', '5', 'COCO-S03-C05-0009', 'Gậy Đánh Mỡ Đả Thông Kinh Lạc, Gậy Gỗ Sồi Thơm Giảm Béo Bụng Spa Dưỡng Sinh', 'Gậy Đánh Mỡ Đả Thông Kinh Lạc, Gậy Gỗ Sồi Thơm Giảm Béo Bụng Spa Dưỡng Sinh
 Phân loại: Gậy 5-8-10-20-31 hạt bi
 Đặc điểm:
 1, Que cạo hạt đôi 60cm dài 60cm.
 2, Thiết kế cầm tay, dễ sử dụng. Độ che phủ rộng, cạo lưng, tuyệt vời cho toàn bộ cơ thể, đầu, vai, chân, cánh tay, lưng, bàn chân, bàn tay và giảm đau cơ.
 3, Gậy cạo gỗ cacbon hóa, lưng, vai, cổ, dụng cụ massage chân và đầu, nạo massage đốt cháy chất béo mỏng, nhiều sự lựa chọn của thẩm mỹ viện.
 4, Thiết kế lồi lõm đặc biệt, biên độ uốn cong rãnh phù hợp hơn với đường cong cơ thể con người, và độ dài khác nhau phù hợp với các bộ phận khác nhau của cơ thể. Giảm mệt mỏi, đau cơ và cứng khớp một cách hiệu quả.
 5, Gậy massage cạnh siêu mịn sẽ không làm trầy xước và gây hại cho làn da của bạn. 6, Kích thước tốt, trọng lượng nhẹ, dễ mang theo và thoải mái khi cầm.
 7, Gỗ cacbon hóa, chống ẩm, không có gờ, chất lượng gỗ cứng, được sử dụng để xoa bóp các huyệt đạo, lăn meridians, bấm huyệt và cạo.
 Hướng dẫn sử dụng:
 1) Đối với mặt sau: Đầu tiên sử dụng bề mặt lõm từ trên xuống dưới, mỗi lần theo cùng một hướng. Sau đó, sử dụng bề mặt lồi để cạo cột sống.
 2) Đối với bụng: Lấy rốn làm trung tâm, massage từ trên xuống dưới, cường độ đều, không cần dùng lực quá mạnh, ruddy rất tốt. Nói chung tuân thủ ba ngày đến một tuần, táo bón có thể được cải thiện.
 3) Đối với chân: Bắt đầu từ đầu gối, xuống, chỉ theo cùng một hướng mỗi lần (nếu có tĩnh mạch giãn hoặc phù nề ở chi dưới, bạn phải từ dưới lên trên để cải thiện máu Tuần hoàn)
 4) Đối với vai và cổ: Từ trên xuống dưới, tần số hoạt động phải chậm và nhất quán, không quá nhanh, lực không được quá nặng. Chuyển động nhẹ nhàng có thể giúp lưu lượng bạch huyết, giảm sự thiếu máu cung cấp cho đầu, vai và cổ bị tắc nghẽn cổ, v.v.
 Mỗi nơi là 3-5 phút. "', '2000'),
