  1. Nắp Hồng (Sensitive Skin):
 - Dành cho: Da nhạy cảm, da khô.
 - Công dụng: Làm sạch dịu nhẹ nhất, cấp ẩm, không gây khô căng. "Chân á" cho mọi loại da.
 2. Nắp Vàng (Vitamin C):
 - Dành cho: Da xỉn màu, da không đều màu.
 - Công dụng: Bổ sung Vitamin C giúp làm sáng da, mờ thâm và lấy đi tế bào chết nhẹ nhàng.
 3. Nắp Xanh (Salicylic BHA):
 - Dành cho: Da dầu, da mụn.
 - Công dụng: Chứa Salicylic BHA giúp kiểm soát dầu thừa, giảm mụn và sạch sâu bụi mịn PM2.5.
