 - An toàn: Công thức 0% Cồn & Không hương liệu, không gây kích ứng.
 - Kết cấu tươi mát: Dạng nước lỏng nhẹ, không bết rít, tạo cảm giác thoáng sạch tức thì.
 - Đa năng: Tẩy sạch cả vùng mắt và môi cực kỳ êm ái.
 5. Hướng dẫn sử dụng:
 - Thấm dung dịch ra bông tẩy trang. Lau nhẹ nhàng lên mặt, mắt và môi. Không cần rửa lại với nước (riêng dòng BHA/Vitamin C có thể massage nhẹ trước khi lau).
