 Để nơi khô ráo, thoáng mát.
 Đậy nắp kín sau khi sử dụng.
 5. Hướng dẫn sử dụng
 Bước 1: Bạn nên dưỡng ẩm và làm mềm môi trước khi thoa son
 Bước 2: Sử dụng đầu cọ thoa son lên môi theo hình dáng và khuôn môi của bạn. Bắt đầu từ giữa môi và thoa ra hai bên. Nếu muốn màu sắc tươi sáng hơn, bạn có thể dặm thêm một lớp son nữa.
 Bước 3: Dùng đầu ngón tay hoặc cọ nhỏ nhẹ nhàng tán đều son trên môi để tạo hiệu ứng mờ và đều màu.
 Bước 4: Nếu cảm thấy môi khô hoặc cần thêm độ bóng, bạn có thể dặm thêm một lớp son mỏng phủ lên trên.
 6. Những lưu ý khi sử dụng son
 Chọn màu son hợp với tông da
 Không sử dụng son giả, son đã hết hạn
 Thường xuyên tẩy tế bào chết cho môi để màu son lên chuẩn nhất
