('1', '2', 'COCO-S01-C02-0012', '[Rom&nd] Son tint nước siêu lì, lâu trôi Hàn Quốc Romand Glasting Water Tint 4g', 'SON TINT NƯỚC LÂU TRÔI ROMAND GLASTING WATER TINT
 Son tint lì Romand Glasting Water Tint là son tint lì của thương hiệu Romand có chất son tint bóng tự như một lớp màng nước lướt nhẹ trên môi, chứa nhiều dưỡng chất giúp nuôi dưỡng đôi môi, son lên môi nhẹ và mướt mịn, dễ tán đều cùng với bảng màu rực rỡ đa dạng mang đến cho bạn đôi môi căng mọng tràn đầy sức sống, tự tin cả ngày dài
 THÔNG TIN SẢN PHẨM
 - Son có thiết kế bên ngoài với nắp son trong suốt được trang trí bởi dòng chữ Romand. Thân son hình trụ tròn, cầm khá chắc tay và có màu trùng với màu son bên trong
 - Son có kết cấu tint bóng với lớp bóng trong suốt tách biệt với lớp satin màu rất đặc biệt
 - Lớp bóng tách biệt với phần màu cho bạn cảm giác mỏng nhẹ và trong suốt tựa như nước
 - Phần màu tiệp vào môi giúp màu được giữ lâu hơn, lớp tint bóng mang cảm giác bóng sáng cho môi
 - Màu son tiệp vào môi ngay khi apply lên môi, bền màu, độ bám màu cao và giữ màu lâu trong thời gian dài
 - Mang đến vẻ đẹp như đang ngậm nước mà không hề bết dính
 - Cho bạn trải nghiệm bờ môi căng mọng và ẩm mịn, sáng bóng trong trẻo đầy sự lôi cuốn 
 BẢNG MÀU THỜI THƯỢNG
 - 🔥 02 Red Drop : Đỏ thẫm
