 HƯỚNG DẪN SỬ DỤNG/ LƯU Ý
 Cách thoa son lòng môi:Thoa son vào giữa lòng môi trên và dưới.Bặm môi và dùng tay tán đều để đạt hiệu ứng đôi môi chúm chím.
 Cách thoa son cả môi: Thoa son từ lòng môi đến khóe môi. Dùng đầu vát chéo để viền môi sắc nét.Thoa son thêm lần nữa để son lên chuẩn màu.
 HƯỚNG DẪN BẢO QUẢN
 - Lưu ý tránh để sản phẩm tiếp xúc trực tiếp với ánh sáng, những nơi có nhiệt độ quá thấp, hoặc nhiệt độ quá cao
 VỀ THƯƠNG HIỆU ROMAND
 Romand là thương hiệu mỹ phẩm đến từ Hàn Quốc ra mắt vào năm 2017, hướng đến phong cách trẻ trung và năng động. Các sản phẩm từ nhà Romand luôn tạo được tiếng vang và nhận được sự yêu thích nồng nhiệt vì giá thành hợp lý, chất lượng ưng ý và luôn dẫn đầu các xu hướng mới lạ.
 ● Xuất xứ thương hiệu: Hàn Quốc
 ● Sản xuất tại: Hàn Quốc
 ● Dung tích: 4g
