('1', '5', 'COCO-S01-C05-0011', 'Miếng Dán Massage Xung Điện, Máy Masage Điện Thông Minh,  Chân, Cổ, Vai, Gáy 10 Chế Độ Rung Masage Xoa Bóp Giảm Đau.', 'Miếng mát xa xung điện - Trợ thủ thư giãn và chăm sóc sức khỏe tại nhà
 Miếng mát xa xung điện là một thiết bị nhỏ gọn, tiện lợi, mang đến cho bạn trải nghiệm massage chuyên nghiệp ngay tại nhà. Với thiết kế thông minh, sản phẩm này giúp bạn xua tan mệt mỏi, giảm đau nhức cơ bắp và thư giãn tinh thần sau những giờ làm việc căng thẳng.
 💖👓🍈🥝🍍🍑🍒
 🥝🍍Tính năng nổi bật:
 - Công nghệ xung điện tiên tiến: Sử dụng xung điện tần số thấp để kích thích các cơ, giúp giảm đau, tăng cường tuần hoàn máu và phục hồi cơ bắp.
 - Nhiều chế độ massage đa dạng: Bao gồm các chế độ như đấm bóp, xoa bóp, nhào nặn, bấm huyệt, giúp bạn tùy chỉnh theo nhu cầu và sở thích.
 - Thiết kế nhỏ gọn, tiện lợi: Dễ dàng mang theo bên mình và sử dụng ở bất cứ đâu.
 - Điều khiển dễ dàng: Bảng điều khiển trực quan với các nút bấm rõ ràng, giúp bạn dễ dàng lựa chọn chế độ và cường độ massage.
 - Sạc nhanh, sử dụng lâu: Thời lượng pin dài, cho phép bạn sử dụng liên tục trong nhiều giờ.
 🍑🍒Lợi ích khi sử dụng:
 - Giảm đau nhức cơ bắp, giảm căng thẳng và mệt mỏi.
 - Tăng cường tuần hoàn máu, cải thiện sức khỏe.
 - Thư giãn tinh thần, giảm stress.
 - Phục hồi cơ bắp sau khi tập luyện thể thao.
 - Mang lại cảm giác thư thái, dễ chịu.
 👓🍈Đối tượng sử dụng:
 - Người thường xuyên bị đau nhức cơ bắp, mỏi vai gáy.
 - Người làm việc văn phòng, ít vận động.
 - Người tập luyện thể thao.
 - Người muốn thư giãn sau những giờ làm việc căng thẳng.', '149000'),
('3', '4', 'COCO-S03-C04-0003', 'Thùng 100 chiếc khẩu trang 5D Loka mask kháng khuẩn 3 lớp nhiều màu', 'Mô tả sản phẩm 100 chiếc khẩu trang 5D LOKA kháng khuẩn hàng chính hãng LOKA
 Thùng 100 chiếc khẩu trang 5D LOKA hàng chính hãng LOKA
 Tên sản phẩm: khẩu trang 5D LOKA 3 lớp kháng khuẩn
 Xuất xứ: Việt Nam
 Đối tượng sử dụng : Người lớn
 Màu sắc: Trắng, Xanh, Hồng, Đen, XÁM, BE
 THÔNG SỐ SẢN PHẨM:
 • Tiêu chuẩn khẩu trang BFE, VFE, PFE ≥ 99%.
 • Loại: 3 lớp (2 lớp vải không dệt, 1 lớp meltblown)
 HƯỚNG DẪN SỬ DỤNG:
 • Bước 1: Dùng 2 tay sạch để mở khẩu trang
 • Bước 2: Mang 2 dây qua tai. Điều chỉnh dây cho vừa với khuôn mặt và tạo cảm giác dễ chịu
 • Bước 3: Dùng ngón tay trỏ điều chỉnh khẩu trang cho khít mũi
 • Bước 4: Dùng 2 ngón tay phủ toàn bộ khẩu trang cho vừa vặn và sát với khuôn mặt của mình
 CÔNG DỤNG VÀ ƯU ĐIỂM:
 • Thun đeo tai mềm, vải không dệt SMS Pluss 3+ và SS kháng nước.
 • Sản phẩm sử dụng 1 lần, sản phẩm không giặt tái sử dụng.
 • Chất liệu vải cotton không dệt thoáng khí.
 • BFE, VFE, PFE ≥ 99% giúp khả năng lọc khuẩn, bụi tốt nhất.
 • Ngăn ngừa tia UV tiếp xúc da trẻ em.
 • Khẩu trang thiết kế 5D thông minh ôm sát, hàn siêu âm dọc thoáng khí không gây cảm giác ngộp cho trẻ, tạo cảm giác thoải mái, dễ chịu khi đeo.', '50000'),
