('2', '4', 'COCO-S02-C04-0004', 'Hộp 50 Khẩu trang 3D công nghệ dập Nhật Bản hộp 50 cái', 'Hộp 50 Chiếc Khẩu Trang 3D MASK Chống Bụi PM 2.5
 1. Quy cách đóng gói :
 + 1 Hộp 50 chiếc khẩu trang
 + Đóng trong túi nilon tiêu chuẩn
 2. Xuất xứ
 + Việt Nam
 + Đơn vị sản xuất : Công TY Trung Hiếu
 3. Thông tin sản phẩm
 + Phần thân được làm từ Polyester và vải lọc, có cấu trúc đa lớp giúp ngăn khói, bụi, phấn hoa, vi khuẩn xâm nhập phòng chống các dịch bệnh nguy hiểm lây qua đường hô hấp.
 + Thích hợp với các hoạt động thể thao, đi xe đạp trong thành phố nơi có nhiều bụi và khí thải từ động cơ đốt trong và bụi từ các công trường xây dựng, công nhân làm việc ngoài công trường, xưởng, kho... nơi phát sinh ra bụi mịn PM2.5
 + Quai khẩu trang được làm từ Elastic Fabric, co giãn và mềm mại, không gây đau và khó chịu khi sử dụng.
 Thiết kế 3D thông minh cùng cấu trúc lọc đa lớp giúp ôm vừa khuôn mặt cho cảm giác thoải mái, dễ dàng hít thở mà vẫn giữ nhiệt, độ ẩm cho mũi và họng (vào mùa đông). Sử dụng hiệu quả khi lưu thông trên đường.
 Thoải mái giao tiếp. không lem son môi.
 + Khẩu trang không dính vào miệng, không dính son, đây là đặc tính cực kỳ quan trọng của khẩu trang
 + Thiết kế 3D nên ôm vừa vặn khuôn mặt, giúp cho bạn có cảm giác rất thoải mái
 + Đặc biệt không dính son lên khẩu trang,
 + Không làm mờ kính khi đeo khẩu trang, điểm khác biệt cực lớn giữa 3D Mask Monji so với những khẩu trang 3D Mask còn lại
 + Quai đeo êm ái, mềm mại, không làm đau tai và không gây hằn trên khuôn mặt khi đeo lâu.
 + Với các bé có thể buộc lại phần tai đeo để đeo nhé
 Khẩu trang 3D FA (màu Trắng)
 4. Tên và tổ chức chịu trách nghiệm về hàng hóa
 + Cơ sở sản xuất khẩu trang Trung Hiếu
 + Địa chỉ : Xuân Lai, Gia Bình, Bắc Ninh', '27000'),
('1', '2', 'COCO-S01-C02-0013', 'Son Dưỡng Môi Astrid Tái Tạo Môi Từ Mỡ Hươu 4.7gr', 'Son Dưỡng Môi Astrid Mỡ Hươu 4.7gr là sản phẩm dưỡng môi cả ngày lẫn đêm, đem đến đôi môi căng mọng hồng hào tức thì cho các cô nàng. Cung cấp dưỡng chất, cân bằng độ ẩm, thúc đẩy tái tạo tế bào.
 *** XIN LƯU Ý: Son có thành phần là mỡ hươu nên dễ bị biến dạng (chảy, mềm) do nhiệt độ trong quá trình vận chuyển tuy nhiên không ảnh hưởng đến chất lượng son nhé ạ.
 Boshop đã chú thích kĩ ở sản phẩm hình ảnh và in ghi chú HDSD gửi kèm đơn hàng mong khách có thể làm theo hướng dẫn khắc phục, hoặc khách có thể inbox shop ngay để được hỗ trợ nhé! 
 Sản phẩm son dưỡng môi nhận được cơn mưa lời khen từ các beauty blogger nổi tiếng này, đến từ thương hiệu làm đẹp – Astrid, Cộng hòa Séc là một thương hiệu mỹ phẩm của Séc. Thành phần của sản phẩm đều đặc biệt an toàn không gây kích ứng hay dị ứng khi sử dụng. Tinh chất từ mỡ hươu cũng được bổ sung để dưỡng môi hiệu quả hơn. Sản phẩm này chính là những gì mà bạn tìm kiếm cho đôi môi của mình.
 Son dưỡng môi còn đóng vai trò như một lớp son lót trước khi trang điểm để son lì lên màu được chuẩn hơn, cũng như không để lộ rãnh môi và không gây khô hay căng môi. Nghĩa là khi trang điểm, bạn có thể dùng sáp dưỡng môi để làm lớp son nền.
 Màu son sẽ lên đều màu, sáng bóng hơn. Đặc biệt là khả năng bám son được lâu và tự nhiên hơn suốt hàng giờ. Son Dưỡng Môi Astrid Mỡ Hươu có thể dùng cho những môi khô vào thời tiết khô hanh.
 Nhanh chóng cải thiện sắc tố da môi, một đôi môi hồng hào là điều dễ dàng nằm trong tầm tay khi bạn sử dụng son dưỡng môi thường xuyên. Đặc biệt, với thành phần chuyên biệt, giàu dưỡng chất mà son dưỡng môi Astrid cung cấp độ ẩm tối đa cho môi từ sâu bên trong cũng như tạo thành lớp hàng rào ngăn chặn sự mất nước từ da môi.
 Nhờ thành phần có trong sản phẩm được kiểm chứng là an toàn và không gây kích ứng hay ảnh hưởng đến sức khỏe nên bạn hoàn toàn có thể yên tâm sử dụng. Được chiết xuất từ mỡ hươu nguyên chất trải qua quá trình sản xuất nghiêm ngặt, mang đến sản phẩm son dưỡng mỡ hươu Astrid, giúp cấp ẩm cần thiết, làm mềm môi đồng thời hiệu quả thâm môi. Chính vì thế, một đôi môi căng mọng, hồng hào, nói không với tình trạng khô môi, bong tróc là điều nằm trong tầm tay khi bạn sử dụng sản phẩm son dưỡng môi này.
 Hướng dẫn sử dụng:
 Sử dụng sáp dưỡng môi như son dưỡng môi thông thường.
 Thoa sáp dưỡng khi môi khô, nứt nẻ.
 Lưu ý và bảo quản:
 Sử dụng vào buổi tối trước khi đi ngủ 2-3 lần/ tuần để chăm sóc đôi môi mịn màng, căng tràn sức sống.
 Bảo quản nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.
 Tránh xa tầm tay trẻ em và đậy nắp kín sau khi sử dụng.', '44000'),
