 HƯỚNG DẪN SỬ DỤNG
 Tháo dây sạc trước khi dùng,
 - Bấm nút nguồn 1 cái để xem mức pin hiện tại
 - Đè nút nguồn 2 Giây để KHỞI ĐỘNG, sau đó bấm nút nguồn để tăng tốc
 - Đè máy mạnh vào người thì máy sẽ đánh cực mạnh để đánh vùng mỡ bụng hoặc vai, đùi ạ
 - Đè nút nguồn 2 Giây để TẮT.
 Chú ý: Sạc bằng dây sạc kèm theo máy, đừng sạc bằng dây điện thoại máy sẽ không nhận pin
 ĐẶC ĐIỂM MÁY MASSAGE 360
 - Máy mát xa được thiết kế nhỏ gọn, dễ dàng sử dụng với cả những những người có bàn tay nhỏ, có thể đặt gọn gàng trong túi của bạn. Cũng bởi vậy, thành viên nào trong gia đình cũng có thể sử dụng. 
 - Dễ dàng mang đi trong những chuyến đi xa bởi nó được trang bị cổng sạc Type C, loai cổng chung với nguồn sạc của các thiết bị di động. Nên bạn không cần lo hết pin khi mang ra ngoài. 
 - Lớp vỏ bên ngoài được làm từ ABS dẻo chịu lực rung sốc, lực va đập cao, an toàn khi sử dụng. Bên cạnh đó motor được cải tiến tăng tuổi thọ sử dụng cho pin, dùng công nghệ rung cộng hưởng tạo ra lực đánh vào các cơ quan đang mỏi trên cơ thể. 
 THÔNG SỐ KỸ THUẬT
 Màu sắc: Xám/ Đen/ Xanh lá/ Đỏ
 Kích thước sản phẩm: 13*13,3*5cm
