 Tốc độ xoay: 1800-3200
 Đầu massage: 4 đầu và 6 cấp độ
 Thời gian sạc pin: 30 PHÚT
 Pin: Lithium dung lượng 1500mAh tiết kệm và sạc nhanh hơn
 Hỗ trợ sạc với chân Type C
 TÍNH NĂNG CỦA MÁY MASSAGE 360
 Chức năng chính của máy mát xa là giảm căng cứng cơ, đau nhức, tăng cường sự lưu thông máu. 
