('2', '5', 'COCO-S02-C05-0014', 'Đai lưng JUSUKE đai tự làm nóng từ đá tourmaline kết hợp từ tính đai giảm đau lưng, thoát vị, định hình cột sống', 'giới thiệu tới bạn mẫu đai nịt bụng chính hãng JUSUKE phiên bản Pro (là bản nâng cấp, nhất với thiết kế mới và chất liệu cao cấp, đàn hồi tốt, bảo vệ thắt lưng, phân tán lực tốt hơn, nhiệt độ lên đều và ổn định hơn, giúp cho cột sống đúng chuẩn đường cong sinh lý tự nhiên vốn có của cơ thể.)
 Đai lưng JUSUKE đai tự làm nóng giảm đau lưng, thoát vị, hỗ trợ và định hình cột sống
 Mô tả:
 Đai nịt làm từ đá nhiệt Tourmaline được sản xuất dựa trên nền vải có chứa các tinh thể tourmaline đường kính 3mm, và một hệ thống nam châm vĩnh cửu. Từ trường, các ion âm, tia hồng ngoại bước sóng dài xuất hiện từ cơ thể khi được sưởi ấm lên, thâm nhập vào các lớp sâu của da, phá hủy các gốc tự do đang hoạt động và các chất có hại khác. Kết quả của việc tác động này là sự thư giãn của cơ trơn của các cơ quan nội tạng, sự giãn nở của các mạch máu, cải thiện tuần hoàn máu và lưu thông hệ bạch huyết, làm tăng hàm lượng oxy trong máu, kích hoạt năng lượng các tế bào, điều chỉnh hoạt động của hệ thần kinh, tăng cường chức năng miễn dịch của tế bào. Nhờ việc sử dụng đai lưng tourmaline giúp bình thường hóa sự lưu thông máu, loại bỏ các triệu chứng gây ra do lạnh và ẩm ướt, loại bỏ hiện tượng tắc nghẽn, giảm đau, tăng sức chịu đựng của cơ thể, giảm stress, cải thiện giấc ngủ, làm giảm sự hao mòn của các khớp xương, giảm căng cơ bắp, có tác dụng phục hồi chung cho toàn bộ cơ thể. Sự tác động đồng thời của nhiều thành phần tích cực (từ trường, bức xạ hồng ngoại, ion âm) đem đến hiệu quả lâu dài ổn định cải thiện sức khỏe.
 Đai lưng phiên bản cao cấp với cơ chế làm nóng tự nhiên từ đá núi lửa giúp lưu thông khí huyết tới các vùng xương khớp bị tổn thương, qua đó giúp giảm đau lưng hiệu quả.
 - Đai lưng Nhật Bản có 16 viên đá núi lửa ở sau lưng, được chia làm 4 hàng, mỗi hàng 4 viên. Khi đeo vào người từ 15 đến 30 phút đá sẽ từ từ nóng lên mà không cần dùng pin hay điện, cực kỳ tiện dụng.
 - Phía trước bụng có 8 viên đá, 4 hàng mỗi hàng 2 viên. Đá nóng lên giúp giảm mỡ bụng hiệu quả.
 - Sau lưng có 3 thanh kim loại được thiết kế cong theo đường cong theo xương cột sống giúp lấy lại đường cong sinh lý tự nhiên dành cho người bị thiết vị đĩa đệm.
 Đặc tính của đá là tiếp xúc với nhiệt độ và độ ẩm trên da sẽ giải phóng tia hồng ngoại và ion âm làm nóng và hỗ trợ tốt cho sức khỏe.
 Đặc tính chữa bệnh của đá nhiệt tourmaline:
 - Giảm đau mỏi lưng, cột sống, hỗ trợ các bệnh lý thoái hoá, thoát vị
 - Thư giãn cơ, cải thiện tuần hoàn máu
 - Phục hồi, cải thiện sức khỏe cho cơ thể
 - Cân bằng dòng sinh học, ngăn bức xạ có hại
 - Hỗ trợ giảm mỡ bụng hiệu quả nhờ khả năng làm nóng của đá tourmaline
 Phân lập các tia hồng ngoại,
 Phân lập các ion âm,
 Cân bằng dòng sinh học trong cơ thể con người,
 Kích hoạt tế bào nhờ có trường năng lượng tự nhiên,
 Bảo vệ hiệu quả chống lại các bức xạ có hại,
 Chứa một lượng lớn các nguyên tố vi lượng và điều chỉnh chức năng sinh lý của cơ thể.
