('1', '5', 'COCO-S01-C05-0015', 'Máy Massage Xung Điện Trị Liệu 4 Miếng Dán Massage Cổ Vai Gáy.', 'Máy Massage Xung Điện Trị Liệu 4 Miếng Dán
 - Bộ sản phẩm gồm: 1 máy xung điện, 1 bộ dây gắn miếng dán, 4 miếng dán, 1 cáp sạc cổng usb, sách hướng dẫn
 Phương pháp điện xung trị liệu
 - Máy mát-xa trị liệu Health Herald SYK 208 sử dụng phương pháp trị liệu bằng xung điện, có tác dụng điều trị các chứng: đau lưng, đau thần kinh tọa, bong gân, căng cơ, liệt mặt, khớp, các bệnh về cổ và đột sống, viêm vai, viêm tuyến tiền liệt mãn tính, viêm thanh quản mãn tính, sẹo sau phẫu thuật, tổn hại thần kinh, đau bụng. Ngoài ra, máy còn chức năng thẩm mỹ giúp bạn giảm cân, làm đẹp da, thải độc tố, giãn cơ bụng sau khi sinh, nâng ngực chảy sệ.
 - Thiết kế tiện dụng
 - Với kích thước nhỏ gọn, vừa vặn tay cầm cùng khả năng sử dụng điện năng tự pin AAA, máy Health Herald SYK 208 hỗ trợ người sử dụng mang theo bên người mọi lúc mọi nơi. Ngoài ra, bạn cũng có thể sử dụng nguồn điện sạc cho máy bằng cách cắm sạc qua cổng USB rồi nối với máy.
 Hướng dẫn sử dụng
 - Cách đặt vị trí miếng gel điện cực:
 + Làm sạch nơi cần điều trị bằng khăn ướt.
 + Loại bỏ các giấy bảo vệ trên các tấm lót gel điện cực, và đặt miếng gel điện cực vào nơi cần được điều trị một thời gian. Lưu ý: Các miếng gel điện cực nên được đưa vào cơ thể cùng 1 lúc, nếu không máy massage không thể làm việc, không cần phải đặt các miếng lót đối xứng.
 - Bắt đầu: Khi bạn bấm vào nút On/0ff, khi đó màn hình LCD sẽ hiển thị mode cho bạn lựa chọn các chế độ khác nhau của máy, chế độ mặc định của máy là chế độ bấm huyệt và thời gian điều trị là 15 phút.
 - Chọn ngôn ngữ: tiếng Anh
 - Chọn chế độ: ấn mode để chuyển chế độ mà bạn yêu thích.
 - Lựa chọn cường độ: ấn nút cường độ lên và xuống (để tăng lên hoặc giảm xuống 1 cấp) theo đó bạn có thể lựa chọn cường độ thích hợp.
 - Chọn thời gian điều trị: nút hẹn giờ để lựa chọn thời gian điều trị phù hợp
