('3', '2', 'COCO-S03-C02-0014', 'Son Kem Lì Black Rouge màu DL6 đỏ nâu pha cam son blackrouge dl6', 'chất son khá lạ khi lai giữa gloss và velvet, tạo độ bóng khá nhẹ cho môi căng mọng tự nhiên
 BLACK ROUGE DL01 – Salmon layer: Màu hồng đào san hô tươi sáng và tinh tế.
 BLACK ROUGE DL02 – Mute layer: Màu hồng lạnh đặc trưng, mang đến vẻ ngoài dịu nhẹ và thuần khiết.
 BLACK ROUGE DL03 – Fauve layer: Màu cam quế ấm áp, tạo cảm giác ấm cúng và trẻ trung.
 BLACK ROUGE DL04 – Chili layer: Màu đỏ thuần đậm nổi bật, đem lại sự quyến rũ và sự tự tin.
 BLACK ROUGE DL05 – Taro layer: Màu đỏ nâu cherry trầm lắng, tạo vẻ đẹp cổ điển và quyến rũ.
 BLACK ROUGE DL06 – Woody layer: Màu đỏ nâu pha cam tạo nên sự ấm áp và nổi bật, phù hợp với nhiều tông da và phong cách trang điểm
 BLACK ROUGE DL07 - Fauvism Red - Màu cam đỏ tươi
 BLACK ROUGE DL08 - Apricot Nudeism - Màu be nude
 BLACK ROUGE DL09 - Modern Orange - Ánh cam khói
 BLACK ROUGE DL10 - Romantic Pink - Sắc hồng rose:
 BLACK ROUGE DL11 - Dada Chill - Sắc đỏ táo
 BLACK ROUGE DL12 - Cubism Brick - Màu gạch cam
 BLACK ROUGE DL13 - Gothic Jujube - Đỏ gạch đậm
 BLACK ROUGE DL14 - Maximal Brown - Nâu gạch đất
 THIẾT KẾ
 - Vỏ son trong suốt và chắc chắn, được phủ mờ tạo sự sang trọng, thanh lịch và thời thượng.
 - Điểm đặc biệt của thiết kế nằm ở Logo Black Rouge được khắc laser chìm vô cùng tinh tế, hiện đại và thời trang. Dù ở góc độ, thỏi son cũng toát lên thần thái “chanh sả” và thu hút một cách lạ kì!
 - Với đầu cọ vuông vắn được bo tròn ở các góc cạnh giúp thao tác khi tô son dễ dàng hơn. Liều lượng son lấy ra cũng được tiết chế phù hợp hơn, tránh tình trạng son bị dây ra quá nhiều. 
 MÙI HƯƠNG : Mang đậm hương vị ngọt ngào, béo ngậy vô cùng quyến rũ của món tráng miệng đến từ Pháp - Cream Brulee 
 HIỆU QUẢ
 - Velvet Layer: Lần lướt cọ đầu tiên sẽ cho ra lớp son nhung mịn lì, tạo cảm giác mềm mại như lông vũ chạm môi.
 - Matt Gloss Layer: Những lần lướt cọ tiếp theo sẽ cho ra lớp phủ mịn màng kèm theo một chút hiệu ứng óng ánh, khiến đôi môi thu hút và nổi bật hơn.
 - Tint Layer: Sau thời gian dài sử dụng, đôi môi sẽ giữ lại 01 lớp màu tint nhẹ nhàng và tự nhiên, khiến đôi môi luôn ở trạng thái đẹp nhất!
 - Màu sắc lên rõ nét từ lần lướt cọ đầu tiên.
 - Chất son chống lem cực kỳ hiệu quả với lớp finish mịn lì mà căng bóng.
 - Cấp ẩm sâu, che phủ hoàn toàn các khuyết điểm của đôi môi, không làm lộ vân môi và rãnh môi.
 - Thành phần chứa nhiều dưỡng chất có lợi, bảo vệ làn môi triệt để trước những yếu tố từ môi trường.', '273900'),
('1', '5', 'COCO-S01-C05-0016', 'Cây gãi lưng, gãi ngứa inox rút gọn kéo dài 50cm', 'Cây gãi lưng, gãi ngứa inox rút gọn kéo dài 50cm
