 Vật liệu: thép không gỉ
 Màu sắc: bạc
 Kích thước: như hình', '92000'),
('1', '2', 'COCO-S01-C02-0015', 'Nước Làm Sạch Và Tẩy Trang Cho Mọi Loại Da Garnier Micellar Cleansing Water 125ml / 400ml- Dr Thêm', '★ THÔNG TIN SẢN PHẨM
 - Thương hiệu: Xem trên bao bì
 - Xuất xứ: Indonesia
 - Dung tích / Khối lượng: 125ml
 - Loại da phù hợp: Da dầu, Da hỗn hợp, Da nhạy cảm, Da khô
 - Đối tượng sử dụng: Nam và nữ
 + Màu hồng : dành cho da nhạy cảm
 + Màu xanh dương : dành cho da dầu và mụn
 + Màu vàng : giúp làm sáng da , hỗ trợ loại bỏ nám
 + Màu trắng : dành cho mọi loại da, đặc biệt da khô và da trang điểm.
 - Dành cho da khô & trang điểm. Nước làm sạch và tẩy trang đa năng Garnier Micellar Water Oil-Infused 400ml an toàn cho da nhạy cảm. Không chứa cồn, không gây kích ứng da. Kết cấu không nhờn, không bết dính, phù hợp với mọi loại da. Sử dụng công nghệ Micelles (Micellar Technology) kết hợp Dầu hạt Argan thiên nhiên có tác dụng dưỡng ẩm cho da. Phân tử Micelles lấy đi bụi bẩn sâu bên trong lỗ chân lông theo cơ chế hoạt động của nam châm, dầu hạt Argan lấy đi cặn bẩn trang điểm và dưỡng ẩm da.
 - Dành cho da dầu mụn: Nước làm sạch và tẩy trang đa năng Garnier Micellar Water For Oily & Acne-Prone Skin 400ml nhẹ nhàng làm sach da, lấy đi bụi bẩn, cặn trang điểm và dầu thừa gây ra tình trạng mụn. Phù hợp cho da dầu & da hỗn hợp. Lấy đi dầu thừa mà không gây khô da. Sử dụng công nghệ Micelles (Micellar Technology), phân tử Micelles lấy đi bụi bẩn sâu bên trong lỗ chân lông theo cơ chế hoạt động của nam châm khi lau nhẹ trên da mà không cần chà xát.
 - Dành cho da sạm màu: Nước làm sạch và tẩy trang đa năng Garnier Micellar Water Vitamin C 400ml làm sạch sâu và dưỡng sáng da với thành phần Vitamin C & chiết xuất quả Yuzu trong thiên nhiên. Kết hợp Vitamin C có tác dụng dưỡng sáng các vùng da xỉn màu. Kết cấu không nhờn, không bết dính, phù hợp với mọi loại da. Sử dụng công nghệ Micelles (Micellar Technology), phân tử Micelles lấy đi bụi bẩn sâu bên trong lỗ chân lông theo cơ chế hoạt động của nam châm.
 - Dành cho da nhạy cảm: Nước làm sạch và tẩy trang đa năng Garnier Micellar Water For Sensitive Skin 400ml nhẹ nhàng làm sach da, lấy đi bụi bẩn, cặn trang điểm và làm da tươi mát. Công thức lành tính, đặc biệt an toàn trên da nhạy cảm. Đặc biệt an toàn trên da nhạy cảm. Không có cồn & hương liệu. Làm sạch và chăm sóc da dịu nhẹ.
 + Xuất xứ: Indonesia
 + HƯỚNG DẪN SỬ DỤNG:
 + Thông tin dị ứng (nếu có): xem bảng thành phần.
 + Hướng dẫn bảo quản: Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp từ mặt trời. Để xa tầm tay trẻ em.
 + Bao bì thay đổi theo từng đợt nhập hàng.
 + Hạn sử dụng: 3 năm kể từ ngày sản xuất
 ★ THÀNH PHẦN CHÍNH
 Vitamin C & chiết xuất quả Yuzu trong thiên nhiên. Kết hợp Vitamin C có tác dụng dưỡng sáng các vùng da xỉn màu. Kết cấu không nhờn, không bết dính, phù hợp với mọi loại da. Sử dụng công nghệ Micelles (Micellar Technology), phân tử Micelles lấy đi bụi bẩn sâu bên trong lỗ chân lông theo cơ chế hoạt động của nam châm.
 - Dành cho da nhạy cảm: Nước làm sạch và tẩy trang đa năng Garnier Micellar Water For Sensitive Skin 400ml nhẹ nhàng làm sach da, lấy đi bụi bẩn, cặn trang điểm và làm da tươi mát. Công thức lành tính, đặc biệt an toàn trên da nhạy cảm. Đặc biệt an toàn trên da nhạy cảm. Không có cồn & hương liệu. Làm sạch và chăm sóc da dịu nhẹ.
 + Xuất xứ: Indonesia
 +
 ★ HƯỚNG DẪN SỬ DỤNG
 + Thông tin dị ứng (nếu có): xem bảng
 ★ HẠN SỬ DỤNG & BẢO QUẢN
 - Hạn sử dụng: 3 năm kể từ ngày sản xuất
 - Cách bảo quản: Bảo quản nơi khô ráo, thoáng mát, tránh ánh nắng trực tiếp từ mặt trời. Để xa tầm tay trẻ em.
