 - Tránh tiếp xúc trực tiếp với mắt. Nếu tiếp xúc, rửa lại ngay bằng nước sạch.
 - Ngưng sử dụng nếu xuất hiện dấu hiệu kích ứng và tham khảo ý kiến chuyên gia da liễu.
 - Để xa tầm tay trẻ em.', '118000'),
