('2', '5', 'COCO-S02-C05-0016', 'Máy Massage Xung Điện Cổ Vai Gáy, Bắp Tay, Lưng Hình Cánh Bướm 8 Chế Độ Giúp Giảm Đau Nhức Hiệu Quả loại sạc điên', '🎯Chức năng
 ✔️ Miếng dán mỏng nhẹ ôm khít vào vùng cổ, vai gáy, tay chân
 ✔️ Xung điện EMS cực mạnh với tốc độ 1000 lần/phút
 ✔️ Làm mềm cơ, xua tan các cơn đau mỏi nhanh chóng
 ✔️ Dòng điện EMS tần số từ 1-100Hz tùy chỉnh
 ✔️ Massage linh hoạt với 6 kiểu và nhiều cường độ
 ✔️ Có thể sử dụng với nhiều vị trí trên cơ thể
 ✔️ Thiết bị rất gọn nhẹ, có thể mang theo bất cứ đâu
 🎯 Lưu ý:
 - Khi massage bạn nên nới lỏng các cơ bắp để liệu pháp massage được hiệu quả hơn.
 - Miếng dán sau khi sử dụng nên dùng miếng dán bảo vệ dán vào, tránh dơ và khô lớp gel miếng dán.
 - Khi mở máy ra khỏi miếng dán nên dùng một lực vừa đủ tránh làm hư miếng dán.
 🎯 Thông số kỹ thuật :
 - Sử dụng cáp sạc
 - Chế độ massage: 6 (A-F)
 - Tần số: 1-100Hz
 - Thời gian sử dụng: 15 phút
 - Điện áp đầu ra: 9.8mA
 - Kích thước đóng gói: 13.5x15.3x2.8cm
 - Trọng lượng đóng gói: 120g
 👉 cam kết sản phẩm giống hình, giống mô tả 100%
 👉 Sản phẩm được kiểm tra kĩ càng, cẩn thận và tư vấn nhiệt tình trước khi gói hàng giao cho Quý Khách
 👉 Hàng có sẵn, giao hàng ngay khi nhận được đơn
 👉 Hoàn tiền nếu sản phẩm không giống với mô tả
 👉 Giao hàng trên toàn quốc, nhận hàng trả tiền
 👉 Hỗ trợ đổi trả theo quy định của Shopee
 1. Điều kiện áp dụng (trong vòng 07 ngày kể từ khi nhận sản phẩm)
 - Hàng hoá vẫn còn mới, chưa qua sử dụng
 - Hàng hoá bị lỗi hoặc hư hỏng do vận chuyển hoặc do nhà sản xuất
 2. Trường hợp được chấp nhận:
 - Hàng không đúng size, kiểu dáng như quý khách đặt hàng
 - Không đủ số lượng, không đủ bộ như trong đơn hàng
 3. Trường hợp không đủ điều kiện áp dụng chính sách:
 - Quá 07 ngày kể từ khi Quý khách nhận hàng
 - Gửi lại hàng không đúng mẫu mã, không phải sản phẩm của Tổng kho Ferado
 - Không thích, không hợp, đặt nhầm mã, nhầm màu,...
 Do màn hình và điều kiện ánh sáng khác nhau, màu sắc thực tế của sản phẩm có thể chênh lệch khoảng 3-5%
