('1', '2', 'COCO-S01-C02-0016', 'DRCEUTICS Nước Tẩy Trang Ultra-mild OLIVE Cleansing Water Dịu Nhẹ Cho Mọi Loại Da (310ml, 500ml)', 'Nước Tẩy Trang DrCeutics Ultra Mild Olive Cleansing Water Làm Sạch Dịu Da 310ml/500ml
 • Xuất xứ: Việt Nam 
 • Dung tích: 500ml
 ƯU ĐIỂM:
 - Tận dụng tối đa khả năng làm dịu da, làm mềm da và dưỡng ẩm cho da của các chiết xuất, dẫn xuất từ các bộ phận của cây olive, nước tẩy trang Ultra-mild OLIVE Cleansing Water giúp làm sạch da khỏi các tạp chất, nhẹ nhàng làm sạch lớp trang điểm mà vẫn duy trì được tình trạng cân bằng của da, giúp da mềm dịu, không gây khô da, không cay mắt và giúp da thông thoáng, sáng mịn mà không cần rửa lại với nước.
 - Bảng thành phần an toàn, lành tính, không chứa parapen, không cồn khô, không hương liệu, không sulfate giúp hạn chế tối đa kích ứng cho da.
 THÀNH PHẦN CHÍNH:
 -Hydrogenated Olive oil: là một nguồn giàu chất chống oxy hóa giúp bảo vệ da tốt hơn, bên cạnh đó cũng giúp làm mềm và giữ ẩm cho da
 -Olea Europaea (Olive) Fruit Oil: có nhiều acid béo thiết yếu như acid oleic, acid palmitic, acid linoleic,... cùng các hợp chất phenolic giúp bảo vệ da, dưỡng ẩm và làm mềm da, đặc biệt tốt cho làn da khô, yếu. Ngoài ra dầu quả olive cũng giúp làm dịu da cũng như bảo vệ da trước tác động có hại của tia cực tím.
 -Ethylhexyl Olivate: là ester của ethylhexyl alcohol và acid béo có nguồn gốc từ quả olive. Thành phần này giúp làm tăng đáng kể khả năng hydrat hóa da, chức năng rào cản, độ mịn bề mặt da nhờ cấu tạo phân tử tạo ra lớp màng mỏng tích hợp với hàng rào bảo vệ da và cải thiện các đặc tính cảm quan của da.
 - Lauryl Olivate: là một ester có chiết xuất từ quả olive được sử dụng khá phổ biến trong các công thức mỹ phẩm chăm sóc da và tóc. Lauryl olivate được đánh giá là an toàn với nhiều công dụng như phục hồi chức năng hàng rào da và cải thiện độ ẩm cho da. Ngoài ra, lauryl olivate có trong sản phẩm giúp đem lại cảm giác nhẹ nhàng, mềm mại và độ lan tỏa tuyệt vời trên khắp bề mặt da.
 -Olea Europaea (Olive) Leaf Extract (Chiết xuất lá Olive): giàu các hợp chất chứa hoạt tính sinh học như sterols, tocopherols, phenols có tác dụng làm se da, góp phần làm hương liệu trong sản phẩm. Các hợp chất phenol của lá olive tác động chống oxy hóa trực tiếp lên da.
