('1', '5', 'COCO-S01-C05-0020', 'Gối Kê Lưng Công Thái Học, Tích Hợp Massage Chườm Nóng, Đệm Lưng Cao Su Non - Sairui', 'Gối Kê Lưng Tích Hợp Massage Chườm Nóng, Đệm Lưng Chống Đau Lưng, Thoát Vị Đĩa Đệm, Giảm Đau Cột Sống - Sairui Store
 Gối kê lưng Sairui với thiết kế theo công thái học giúp người sử dụng "lấp đầy" vùng hẫng này, từ đó giải phóng áp lực lên cột sống thắt lưng, giúp cột sống luôn theo đường cong sinh lý của cơ thể.
 Gối còn tích hợp 6 chế độ massage và 3 cường độ chườm nóng giúp vùng thắt lưng được thư giãn, giảm các triệu chứng đau nhức.
 CÔNG DỤNG:
 - Giảm đau mỏi lưng dưới (vùng thắt lưng và eo) đặc biệt với đối tượng bà bầu, người cao tuổi, người thường xuyên phải mang vác hoặc cúi người khi làm việc
 - Phòng và hỗ trợ các bệnh cột sống thắt lưng như thoát vị đĩa đệm
 - Kê lưng thư giãn khi ngủ, tựa lưng hoặc đầu khi đặt trên ghế văn phòng hoặc ghế ô tô
 THÔNG TIN CHI TIẾT:
 - Thương hiệu: SAIRUI.
 - Thiết kế: Thiết kế công thái học, chất liệu êm ái.
 - Tính Năng : + Massage mô phỏng tay người, giúp thư giản các cơ vùng lưng.
 + Chườm nóng 3 mức độ, giảm đau sâu vùng thắt lưng.
 - Chất liệu: Cao su non, vải cotton 83% sử dụng chất liệu Dupont, quy trình in và nhuộm hoạt tính ở nhiệt độ cao, mềm mại, thoải mái.
 - Màu sắc: Xám Đen, Xám Trắng.
 - Kê lưng có massage & chườm nóng: Văn phòng, trên ô tô hoặc những người hay bị đau mõi cột sống
 - Kê lưng đổi vị trí: 6 chế độ massage & 3 mức nhiệt độ.
 - Chế độ bảo hành: 12 THÁNG (bộ máy massage). 1 đổi 1 trong 30 ngày đầu tiên nếu lỗi sản xuất.
 HƯỚNG DẪN SỬ DỤNG:
 - Cắm dây và kết nối với dòng điện 5V/2A (đầu USB A nên có thể kết nối với cốc sạc điện thoại, sạc dự phòng).
 - Có thể chuyển đổi qua lại các chế độ cũng như các mức độ massage & chườm nóng.
 LƯU Ý: Gối không tích hợp pin. Không kèm củ sạc.
 SHOP XIN CAM KẾT:
 - Hàng thật, đúng mô tả, quảng cáo.
 - 100% Đổi trả miễn phí với sản phẩm phát sinh lỗi từ nhà sản xuất.
 - Bảo hành bằng hóa đơn điện tử.
 - Trong quá trình vận chuyển rất dễ có khả năng hàng hóa bị bể vỡ hoặc mất hàng, Shop sẽ chịu hoàn toàn 100% cho các trường hợp trên với điều kiện QUÝ KHÁCH VUI LÒNG QUAY VIDEO KHI MỞ HÀNG để làm bằng chứng, các đơn hàng không đủ bằng chứng shop xin phép từ chối bảo hành với lỗi bể vỡ và thiếu hàng !
