('3', '3', 'COCO-S03-C03-0013', 'Kềm cắt da Kềm Nghĩa D01 D04 D09 D205 D401 D18 D555 D777 chính hãng - Kìm nhặt da thép không gỉ chuyên dụng làm nail', 'Kềm cắt da Kềm Nghĩa D01 D555 chính hãng - Kìm nhặt da thép chuyên dụng làm nail
 Kềm cắt da D01, D555... là các sản phẩm của thương hiệu Kềm Nghĩa, một thương hiệu nổi tiếng của Việt Nam chuyên sản xuất các sản phẩm về kềm và các dụng cụ khác chuyên dụng trong ngành nail.
 Kềm nhặt da thép không gỉ và kềm nhặt da thép chuyên dụng là loại dụng cụ được thiết kế đặc biệt để sử dụng trong ngành làm móng (nail).
 Sản phẩm Kềm Nghĩa được chế tác từ chất liệu thép chuyên dụng và thép không gỉ cao cấp, an toàn cho người sử dụng.
 Mũi và lưỡi kềm được thiết kế phù hợp để dễ đi vào phần da và làm sạch phía trong móng. Lưỡi kềm sắc mỏng, tinh xảo, độ chính xác cao nên cắt chính xác gọn gàng không làm tổn thương da khi cắt.
 Chống kềm và rãnh giúp tự động bung cán kềm ra khi cắt mà không cần các ngón tay đẩy giúp người dùng dễ dàng tự cắt da tại nhà.
 ◉ Mũi 14: 5.5 -> 6mm – là cỡ lưỡi trung bình, dùng để cắt da thừa.
 ◉ Mũi 16: 6.5 -> 7mm - là cỡ lưỡi dài nhất, hay còn gọi là lưỡi tiêu chuẩn, cắt cả những mảng da dài hơn phía ngoài kết hợp với đi sâu vào khóe móng.
 Thông tin sản phẩm:
 - Thương hiệu: Kềm Nghĩa
 - Công dụng: Dùng để nhặt da móng tay, chân.
 - Chất liệu: Thép carbon chuyên dụng và thép không gỉ
 - Đặc điểm:
 + D.01: Thép không gỉ, màu xám (mờ), 1 chống, 2 mang vuông, jaw 16, 58gr
 + D.555: Thép chuyên dụng mạ vàng 24K, 1 chống, 2 mang vuông, full jaw, 52gr
 - Quy cách đóng gói: 1 cây
 Hướng dẫn sử dụng:
 - Bước 1: Ngâm móng tay hoặc móng chân trong bát nước, hoặc dùng nước làm mềm da (nếu có)
 - Bước 2: Lau khô móng tay, móng chân
 - Bước 3: Cắt móng tay, móng chân theo mẫu mà khách hàng mong muốn
 Lưu ý:
 - Trước khi sử dụng nên dùng cồn hoặc Acetone khử trùng
 - Sau khi sử dụng lau lại bằng cồn hoặc Acetone rồi bỏ vào bao bì để bảo quản
 - Để nơi khô ráo và tránh xa tầm tay trẻ em
 - Hãy sử dụng riêng bấm móng cá nhân để bảo vệ sức khỏe
 Đặc biệt lưu ý: Mẫu mã và bao bì sản phẩm có thể thay đổi tùy theo từng đợt hàng về của hãng
 Cam kết khi mua hàng tại shop:
 - Shop luôn mang đến cho khách hàng những sản phẩm chính hãng, đảm bảo đúng chất lượng
 - Hình ảnh sản phẩm do nhân viên shop tự chụp 100%
 - Nếu quý khách hàng gặp vấn đề về đơn hàng hãy liên hệ ngay qua tin nhắn để Shop nắm được thông tin và liên hệ sớm nhất!
 Khung giờ phản hồi chat tích cực: 9h-17h
