('3', '2', 'COCO-S03-C02-0019', 'Nước Tẩy Trang Drceutics Ultra-mild OLIVE Cleansing Water 310ml/500ml- Dr Thêm', '★ THÔNG TIN SẢN PHẨM
 - Thương hiệu: DrCeutics
 - Xuất xứ: Xem trên bao bì
 - Dung tích / Khối lượng: 310ml
 - Loại da phù hợp: Phù hợp nhiều loại da
 - Đối tượng sử dụng: Nam và nữ
 CÔNG DỤNG: Làm sạch da khỏi các tạp chất và các hạt ô nhiễm; nhẹ nhàng loại bỏ lớp trang điểm mà
 không gây khô da; làm dịu da; duy trì tình trạng cân bằng của da; giúp da thông
 thoáng, sáng mịn.
 ƯU ĐIỂM: Tận dụng tối đa khả năng làm dịu da, làm mềm da và dưỡng ẩm cho da của các chiết xuất, dẫn
 xuất từ các bộ phận của cây olive, nước tẩy trang Ultra-mild OLIVE Cleansing
 Water giúp làm sạch da khỏi các tạp chất và các hạt ô nhiễm, nhẹ nhàng loại bỏ
 lớp trang điểm mà vẫn duy trì được tình trạng cân bằng của da, giúp da mềm dịu,
 không gây khô da, không cay mắt và giúp da thông thoáng, sáng mịn mà không cần
 rửa lại với nước.
 Bảng thành phần an toàn, lành tính, không chứa parapen, không cồn khô, không hương liệu,
 không sulfate giúp hạn chế tối đa kích ứng cho da.
 ★ HƯỚNG DẪN SỬ DỤNG
 Thấm một lượng vừa đủ ra bông tẩy trang. Lau nhẹ trên da mặt, vùng da quanh mắt và môi nhưng không chà xát mạnh trên da. Sử dụng 2 - 3 lầnngày tuỳ theo nhu cầu làm sạch da.
 ★ HẠN SỬ DỤNG & BẢO QUẢN
 - Hạn sử dụng: 3 năm kể từ ngày sản xuất
 - Cách bảo quản: Bảo quản nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.
 ★ LƯU Ý
 - Sản phẩm này có thể được sử dụng để làm sạch mà không cần rửa lại với nước, đặc biệt thuận tiện khi đang di chuyển hoặc khi không có nước để rửa mặt. Nhờ bản chất mỏng nhẹ và khô thoáng tuyệt đối nên ngay cả khi không rửa lại với nước thì các bước skincare tiếp theo như toner, serum hay kem dưỡng vẫn có thể tiếp tục như bình thường.
 - Đối với các trường hợp da tiết dầu nhiều, môi trường nhiều bụi bẩn - ô nhiễm, hoặc khi có trang điểm (make-up) hoặc khi có sử dụng các loại kem chống nắng kháng nước (water-resistant hoặc waterproof) hoặc các sản phẩm skincare nền dầu (dầu dưỡng, nhũ tương nướcdầu), vv… thì nên rửa lại da bằng một loại sữa rửa mặt phù hợp sau khi tẩy trang.
 - Đối với các sản phẩm makeup chống trôi, không nên chà xát mạnh bông tẩy trang trên da để tránh làm da bị tổn thương. Nên thấm ướt bông tẩy trang bằng nước tẩy trang này và đắp lên vùng da cần tẩy trong khoảng 15 ~ 30 giây để thấm ướt và làm mềm lớp makeup rồi mới lau nhẹ, khi đó lớp makeup sẽ dễ dàng được làm sạch hơn.
 - Cần lưu ý thấm ướt bông cotton bằng nước tẩy trang với lượng vừa đủ. Tránh trường hợp dùng quá nhiều sẽ dễ chảy vào mắt khi tẩy trang vùng quanh mắt. Và cũng không nên dùng lượng quá ít, sẽ khiến bông tẩy trang bị khô, hiệu quả làm sạch kém mà ma sát trên da lại tăng, dễ làm đỏ - rát da.
 - Đối với da có mụn sưng đỏ - mụn mủ, nên sử dụng những miếng bông khác nhau cho vùng da lành và vùng da có mụn, nhằm hạn chế tối đa việc lây lan mụn sang các vùng da khác do thao tác chà xát của quá trình tẩy trang.
 - Không nên sử dụng nước tẩy trang trên các vết thương hở.
 - Hiện tượng dị ứngkích ứng có thể xảy ra với bất kì ai và với bất kì sản phẩm nào, nên cần test trên 1 vùng nhỏ trước khi sử dụng toàn mặt.
 BẢO QUẢN: Bảo quản nơi khô ráo thoáng mát, tránh ánh nắng trực tiếp.
 HSD: 3 năm', '93000'),
('2', '5', 'COCO-S02-C05-0023', '【Bán sỉ】 MÁY MASSAGE HÌNH BƯỚM-8 Chế Độ Xung Điện Cổ Vai Gáy, Bắp Tay, Lưng Giúp Giảm Đau Nhức Hiệu Quả Lọa Sạc Điện【pcs', '♥ ♥ ♥ Mô tả sản phẩm: ♥ ♥ ♥
 Chức năng
