 🎯 Lưu ý:
 - Khi massage bạn nên nới lỏng các cơ bắp để liệu pháp massage được hiệu quả hơn.
 - Miếng dán sau khi sử dụng nên dùng miếng dán bảo vệ dán vào, tránh dơ và khô lớp gel miếng dán.
 - Khi mở máy ra khỏi miếng dán nên dùng một lực vừa đủ tránh làm hư miếng dán.
 🎯 Thông số kỹ thuật :
