('3', '5', 'COCO-S03-C05-0023', 'Máy massage chườm nóng Ovie giảm đau bụng kinh nguyệt, Đai matxa làm ấm nhiệt hồng ngoại cao cấp', 'Máy massage chườm nóng Ovie giảm đau bụng kinh nguyệt, Đai matxa làm ấm nhiệt hồng ngoại cao cấp
 Từ xa xưa, Đông y đã sử dụng chườm nóng giảm phong hàn như phương pháp nâng cao sức khỏe. Tuy nhiên nếu như bạn ngại việc xông chườm nóng phức tạp thì hãy thử Máy massage chườm nóng Ovie. Chiếc máy chỉ nhỏ gọn vừa vặn lòng bàn tay sẽ giúp bạn thấy hài lòng hơn với việc chườm giữ ấm bụng, tay chân...nhiều bộ phận giữa những ngày đông rét mướt này.
 1/ THÔNG SỐ KỸ THUẬT CỦA MÁY MASSAGE CHƯỜM NÓNG OVIE
 • Màu sắc: Trắng
 • Điện áp định mức: 3.7V
 • Dòng điện: 5V
 • Dung lượng pin: 1800mAh
 • Thời gian sạc: 3 h
 • Chống nước: không
 • Trọng lượng: 175g
 • Bộ sản phẩm gồm: 1 máy, 1 dây sạc, 1 sách HDSD
 • Chức năng: làm ấm và rung massage
 • 3 Mức nhiệt: 50oC-55oC-60oC
 • Rung: 3 cấp độ
 • Thời gian hoạt động mặc định: 30 phút
 2/ ƯU ĐIỂM CỦA MÁY MASSAGE CHƯỜM NÓNG OVIE
 • Được trang bị viên pin lớn, máy có thể làm ấm cực nhanh chỉ sau vài giây, giúp giảm thời gian chờ đợi.
 • Máy massage chườm nóng Ovie với tác động kép của nhiệt hồng ngoại kết hợp rung tuần hoàn, nhanh chóng giúp: Giảm đau bụng kinh, giảm đau mỏi lưng hông, căng cứng cơ do ngồi lâu một tư thế hay do thoái hóa, thoát vị, giảm tay chân lạnh và tăng cường lưu thông máu trong mùa đông.
 • Công nghệ rung tần số kép 3 cấp độ làm giãn các cơ đang co thắt, làm giảm các cơn đau bụng kinh nhanh chóng.
 • Máy được trang bị viên pin dung lượng lớn tăng khả năng làm nóng nhanh chóng cũng như kéo dài thời gian sử dụng so với loại thông thường.
 • Mặt vải phần tiếp xúc với bụng mềm mịn, không gây bỏng rát và tạo cảm giác thoải mái, mặt trong được làm bằng nỉ cũng như dây bằng chất liệu cao cấp đem lại cảm giác cực dễ chịu khi sử dụng, cũng như dễ làm sạch sau khi dùng.
 • Đai gồm có 3 mức nhiệt độ (50 độ C giữ ấm hàng ngày, 55 độ C chăm sóc kinh nguyệt, 60 độ C giúp giảm đau bụng khi đến tháng).
 • Đai có 3 chế độ rung massage (F1 rung liên tục, F2 rung/ngừng nhanh, F3 rung/ngừng chậm)
 • Dễ sử dụng và dễ tuỳ chỉnh nhiệt độ, độ rung massage theo ý muốn.
 • Dây đai co giãn và được tuỳ chỉnh rộng nhỏ theo vòng eo khi dùng, Chốt cài dây có thể tháo rời giúp bạn có thể dùng máy cho nhiều vùng khác nhau như lưng, tay, chân chắc chắn.
 3/ HƯỚNG DẪN SỬ DỤNG
 • Cho máy vào vùng cần chườm và massage, điều chỉnh dây vừa vặn.
 • Nhấn và giữ nút nguồn 1 lần cho đến khi đèn sáng để khởi động máy
 • Khi đèn sáng nhấn nhẹ tiếp nút nhiệt (hình nhiệt kế) để chỉnh nhiệt độ, máy có 3 mức nhiệt là 40-50-60 độ. Nếu muốn tắt chế độ làm nóng thì nhấn và giữ nút là máy sẽ tự tắt.
 • Ấn nút bên phải hình rung để bật/thay đổi chế độ rung massage. Máy có 3 chế độ rung F1-F2-F3
 • Khi đã sử dụng xong hãy nhấn giữ nút nguồn để tắt máy hoàn toàn.
 ===LƯU Ý===
 • Không dùng cho bé dưới 14 tuổi, nếudùng phải có sự giám sát của người lớn
 • Không dùng máy khi đang sạc, không để máy những nơi nhiệt độ quá cao hoặc quá thấp
 • Không dùng máy khi đang ngủ
 • Không dùng quá lâu trên 1h cho bất kỳ vùng da nào.
 • Sạc cho máy bằng củ sạc 1A 5V, không dùng các củ sạc có dòng điện cao hơn để tránh bị chai pin
 4/ CAM KẾT VỚI KHÁCH HÀNG:
 • Sản phẩm chính hãng 100%, mới sản xuất.
 • Lỗi 1 đổi 1 trong 7 ngày (lỗi do nhà sản xuất) & theo quy định của Sàn.
 • Giải quyết thắc mắc và vấn đề về sản phẩm (nếu có) cho khách hàng nhanh chóng và thỏa đáng. Nếu gặp bất cứ khó khăn hay vấn đề gì, quý khách vui lòng liên hệ, đừng vội đánh giá xấu về cửa hàng.
 5/ CHÍNH SÁCH BẢO HÀNH
 • Thời gian bảo hành 3 tháng tính từ ngày mua.
 • Sản phẩm được bảo hành khi các hư hỏng của sản phẩm được xác nhận do lỗi của NSX
 • Sản phẩm không được bảo hành khi: chai pin, bị cạy mở, vào nước, va đập', '563000'),
