('2', '5', 'COCO-S02-C05-0025', 'Dụng Cụ Massage Cổ Vai Gáy 6 Bi Cầm Tay Giúp Giảm Đau Tê Nhức Mỏi Hiệu Quả,Cây Massage Cột Sống Cổ Và Toàn Thân Cầm Tay', '👉 Căng cơ, nhức mỏi vùng cổ vai gáy do ngồi lâu, ít vận động, stress kéo dài?
