('3', '3', 'COCO-S03-C03-0014', 'Dụng Cụ Lấy Mụn Bộ 5 Món Que Nặn Mụn Đầu Đen, Trứng Cá, Cám An Toàn Tiện Lợi', 'Bộ 4 Món Que Nặn Mụn Đầu Đen, Trứng Cá, Cám An Toàn Tiện Lợi
 ---------------------------------
 Thép không gỉ cao cấp: 5 dụng cụ nặn mụn được làm từ thép không gỉ cao cấp và được đánh bóng nên có độ cứng cao hơn, bề mặt nhẵn hơn. Và chúng chống gỉ, chống ăn mòn, an toàn khi mài mòn và dễ làm sạch.
 Tay cầm chống trượt và hình dạng tiện dụng: Tay cầm chống trượt có thể giúp bạn điều khiển dụng cụ ổn định và an toàn hơn. Kết cấu chống trượt không chỉ thực tế mà còn đẹp. Hình dạng tiện dụng giúp dụng cụ phù hợp hơn với khuôn mặt của bạn và tránh bị thương hoặc trầy xước trên khuôn mặt.
 ----------------------------
 1.Thông tin sản phậm:
 - Tên sản phẩm
 - Kích thước: 14,5cm*2,5cm - 36g
 - Bộ sản phẩm: 4 cây
 2.Công dụng:
  - Bộ sản phẩm gồm 4 cây nặn mụn có 8 đầu nặn khác nhau, phù hợp với từng loại mụn và kích cỡ mụn.
  - Được làm bằng chất liệu kim loại không gỉ cao cấp, an toàn cho làn da của bạn.
  - Thiết kế nhỏ gọn đựng trrong hộp bạn có thể cất trong túi mang bất cứ nơi đâu.
 3.HƯỚNG DẪN SỬ DỤNG:
  - Chỉ nặn những đốm mụn đã già.
  - Vệ sinh sạch sẽ tay và nhớ dùng cồn để diệt trùng que nặn mụn.
  - Cần chuẩn bị thêm tăm bông hay bông gòn sạch để lấy nhân mụn trên da, tránh dùng tay
  - Nên nặn mụn vào buổi tối vì đây là quãng thời gian da được thả lỏng, trở nên mềm hơn và ít tiếp xúc', '2900'),
('2', '2', 'COCO-S02-C02-0021', 'Nước tẩy trang mắt và môi Maybelline New York Eye & Lip Makeup Remover 150ml', ' Maybelline giới thiệu Nước Tẩy Trang Mắt Và Môi Makeup Remover 2 lớp kèm theo các phân tử nhỏ len sâu giúp làm sạch nhanh chóng &amp; hiệu quả lớp trang điểm mắt &amp; môi. Công thức dịu nhẹ hoàn toàn không gây kích ứng, ngay cả làn da nhạy cảm nhất. Có thể sử dụng cho toàn bộ mặt. Nay với phiên bản bao bì mới, làm 100% từ nhựa tái chế!
 Lời khuyên từ chuyên gia: Chỉ có sản phẩm tẩy trang chuyên dụng mới loại bỏ hiệu quả lớp trang điểm không lem, không trôi thật nhẹ nhàng, không gây hại cho làn da của bạn. Đối với những cô nàng thường xuyên trang điểm thì một chai nước tẩy trang dành riêng cho vùng mắt và môi là không thể thiếu. Đặc biệt khi mắt và môi vốn có làn da mỏng và nhạy cảm hơn những vùng da khác, cần được bảo vệ tốt hơn. Nước Tẩy Trang Mắt Và Môi Maybellinenhẹ dịu nhưng vẫn đảm bảo tẩy sạch các vết trang điểm cứng đầu nhất như mascara không trôi, son lâu phai… trả lại cho bạn làn da mịn tự nhiên.
 • ƯU ĐIỂM NỔI BẬT
 - Nước tẩy trang mắt và môi Eye &amp; Lip Makeup Remover 2 lớp với lớp dầu tẩy trang chuyên dụng và lớp nước làm sạch sâu. - Nước tẩy trang loại bỏ lớp trang điểm không trôi một cách nhẹ nhàng, hiệu quả và nhanh chóng. - Dành cho mọi loại da, kể cả làn da nhạy cảm.
 • HIỆU QUẢ SỬ DỤNG
 Làm sạch nhanh chóng &amp; hiệu quả các lớp trang điểm lâu trôi. Chỉ cần 1 lượng nước tẩy trang vừa đủ là đã có thể cuốn trôi macara hay son kem lì nhanh chóng và không gây rát hay ảnh hưởng vùng da mắt da môi. Được đông đảo tín đồ Makeup tin dùng, nước tẩy trang Maybelline cũng không gây kích ứng, kể cả làn da nhạy cảm như môi và mắt.
 • HƯỚNG DẪN SỬ DỤNG
 Lắc đều trước khi sử dụng để lớp dầu tẩy trang và nước hòa vào nhau, thấm đều sản phẩm lên một miếng bông, đặt lên khu vực mắt và môi vài giây sau đó nhẹ nhàng lau sạch lớp trang điểm trên môi và mắt.
 • THÔNG TIN THƯƠNG HIỆU
 Là thương hiệu trang điểm số 1 thế giới, Maybelline New York chính thức có mặt tại Việt Nam từ năm 2007 và nhanh chóng trở thành thương hiệu trang điểm hàng đầu ở các dòng sản phẩm Mascara, Kem nền, Son kem lì... Sản phẩm của Maybelline luôn ứng dụng công nghệ tiên tiến, dễ sử dụng, dẫn đầu xu hướng Makeup với sự đa dạng về sản phẩm cùng giá thành hợp lý. Maybelline trở thành thương hiệu được yêu thích nhất tại Việt Nam bởi các bạn trẻ thích trang điểm, thích thể hiện chất riêng và dám nghĩ dám làm.
 *Bắt nguồn từ New York- Mỹ và đã có mặt ở hơn 150 quốc gia, Maybelline sở hữu nhiều nhà máy sản xuất trên toàn thế giới như Trung Quốc, Mỹ, Pháp, Nhật,... Dù được sản xuất ở đâu, các sản phẩm đều tuân thủ quy trình kiểm soát chất lượng nghiêm ngặt của Maybelline toàn cầu. Sản phẩm Maybelline chính hãng tại Việt Nam đều có tem nhãn tiếng Việt phía sau và nhập khẩu trực tiếp từ Công ty TNHH L’Oreal Việt Nam nên các bạn hoàn toàn yên tâm về chất lượng và xuất xứ sản phẩm.
 #Maybeline #Nuoctaytrang #dautaytrang #MicellarWater #EyeRemover #Lipremover #Taytrangmatmoi #TaytrangMaybelline', '122870'),
('3', '2', 'COCO-S03-C02-0021', 'Bộ 2 Nước tẩy trang Garnier Cho Da Dầu Mụn Salicylic BHA Micellar 400ml x 2 (mới)', ' Bộ đôi Nước tẩy trang Garnier Cho Da Dầu Mụn Salicylic BHA Micellar 400mlx2 (mới)
 • ƯU ĐIỂM NỔI BẬT
 Nước làm sạch và tẩy trang đa năng Garnier Micellar Water For Oily &amp; Acne-Prone Skin 400ml nhẹ nhàng làm sach da, lấy đi bụi bẩn, cặn trang điểm và dầu thừa gây ra tình trạng mụn. Phù hợp cho da dầu &amp; da hỗn hợp. Không có cồn &amp; hương liệu. Lấy đi dầu thừa mà không gây khô da. Sử dụng công nghệ Micelles (Micellar Technology), phân tử Micelles lấy đi bụi bẩn sâu bên trong lỗ chân lông theo cơ chế hoạt động của nam châm khi lau nhẹ trên da mà không cần chà xát.
 • HIỆU QUẢ SỬ DỤNG
 Làn da sạch thoáng, không còn dầu thừa và giảm bớt nguy cơ gây mụn
 • HƯỚNG DẪN SỬ DỤNG
 Hướng dẫn sử dụng:
 ● Lắc đều, thấm một lượng vừa đủ ra bông tẩy trang
 ● Lau nhẹ trên da mặt, vùng da quanh mắt và môi theo hướng xoay tròn (không chà xát da), không cần rửa lại với nước.
 ● Nên dùng hằng ngày ngay cả khi không trang điểm.
 ● Liều lượng: 1 lần sử dụng = 2ml
 Xuất xứ: Indonesia
 Ngày sản xuất: Xem trên bao bì
 Hạn sử dụng: 3 năm từ ngày sản xuất
 • THÔNG TIN THƯƠNG HIỆU
 Garnier là thương hiệu làm đẹp từ thiên nhiên, chuyên sâu về chăm sóc và bảo vệ sức khỏe làn da. Là sự hòa quyện giữa từ hơn 90% chiết xuất nguyên liệu từ thiên nhiên và công nghệ khoa học – Green Labs, được kiểm nghiệm bởi chuyên gia da liễu, Garnier cung cấp những giải pháp có hiệu quả đã được chứng minh hoàn toàn lành tính &amp; an toàn, chăm sóc da của bạn khỏe đẹp từ bên trong.
 Tất cả các sản phẩm của Garnier, thông qua quá trình sản xuất thân thiện với môi trường, truyền cảm hứng cho người sử dụng về lối sống “xanh”, giải pháp dưỡng da “xanh”, kết nối con người với thiên nhiên và môi trường.
 Garnier nói “KHÔNG” với thử nghiệm trên động vật. Garnier cam kết ngưng sử dụng nhựa nguyên sinh từ năm 2025.', '152700'),
('3', '5', 'COCO-S03-C05-0025', 'Cây mát xa đầu bạch tuộc dùng để massage đầu thoải mái và thư gian tốt - Shop Dbavio', 'Cây mát xa đầu bạch tuộc dùng để massage đầu thoải mái và thư gian tốt - Shop Dbavio
 ---------------------------------
 GIỚI THIỆU SẢN PHẨM :
 - Thư giãn đầu - Bạn thích được mát-xa đầu hay gãi nhẹ , Bạn sẽ thích cây mát-xa da đầu của chúng tôi tốt. Hãy sử dụng một lần và bạn sẽ thích thú.
 - Tăng lưu thông máu , kích thích sự giãn nở : Chỉ cần lướt nhẹ cây mát xa này từ từ trên da đầu, các tế bào thần kinh sẽ được kích thích, sau đó hãy tận hưởng cảm giác "Phê" ran từ da đầu đến tận ngón chân.
 - Đa công dụng : Cây mát xa đầu này có thể dùng để massage da đầu, khớp gối, mắt cá chân, khuỷu tay, v.v.
 - Thiết kế an toàn - Cây mát xa da đầu KINGTECH có các hạt cao su trên mỗi đầu, Khi cây Massage lướt trên da đầu của bạn, đảm bảo an toàn không bị giật tóc cũng như gây xước da.
 - Bạn có thể chia sẻ nó với gia đình hoặc bạn bè của mình. Nếu bạn không hoàn toàn hài lòng vì BẤT KỲ lý do gì, hãy liên hệ với chúng tôi để được hoàn tiền đầy đủ. Hãy tận hưởng cuộc sống của bạn và chia sẻ nó với những người bạn yêu thương.
 - Bạn có thể gửi tặng quà người nhà và bạn thân đảm bảo sẽ thích và sướng
 -----------------------------
 CHI TIẾT SẢN PHẨM : Cây mát xa đầu
 - Chất liệu: Kim loại
 - Hình dạng: Bạch tuộc
 - Chiều dài: 22cm
 - Màu sắc: Ngẫu nhiên
 - Tổng trọng lượng: 20g
