('2', '2', 'COCO-S02-C02-0022', '[Hàng Mới Về] Son Bóng HERORANGE 3D Dưỡng Ẩm Lỏng Chống Thấm Nước Lâu Trôi Tiện Dụng', 'Đây là link mix son, link chứa nhiều loại son. Các nhãn hiệu bao bì đều khác nhau, kiểu dáng bạn nhận được là kiểu dáng trong hình ảnh lựa chọn.
