('3', '5', 'COCO-S03-C05-0026', 'Máy mát xa đeo vai cổ xung điện - máy mát xa hình con bướm - miếng dán massage xung điện cho cổ và vai làm giảm đau nhức cơ bắp', 'Thiết bị massage xung điện dạng miếng dán hình cánh bướm, dùng cho vùng cổ và vai theo tên listing. Sản phẩm tạo xung điện qua điện cực tiếp xúc ngoài da; kiểm tra bộ điều khiển và cách cấp nguồn trước khi dùng.', '2170'),
