('1', '2', 'COCO-S01-C02-0023', 'Xịt Khoáng Cố Định Lớp Trang Điểm Dưỡng Ẩm Kiềm Dầu Lâu Trôi 100ml Xịt Khoá Makeup Nội Địa Trung Xịt Khóa Nền ILY', 'Xịt khoáng/xịt khóa lớp trang điểm ILY dung tích 100 ml theo tên listing. Dùng sau các bước trang điểm để hỗ trợ cố định lớp makeup; tên sản phẩm mô tả dưỡng ẩm và kiềm dầu. Không tự suy diễn thời gian giữ nền cụ thể.', '45000'),
