('2', '2', 'COCO-S02-C02-0023', 'Mousse Velvet Lip Gloss Matte Velvet Whiteing Lip Gloss Sinh viên Giá rẻ Không dễ phai Lip Glo', 'Kết cấu nhung mờ giúp đôi môi của bạn trông mềm mại và tự nhiên hơn. Cảm giác mềm mại và sương mù, đôi môi mềm mại và mỏng manh, nhẹ và mượt, giữ màu mượt mà, trải nghiệm thời gian tự tin và làm đẹp, ở bất cứ đâu.
