('2', '5', 'COCO-S02-C05-0027', 'máy massage cầm tay , massage cổ vai gáy 6 Cấp Độ Chuyên Sâu Đa Năng , máy đấm lưng mát xa đau nhức vai gáy', 'Máy massage cầm tay dùng cho cổ vai gáy, có 6 cấp độ theo tên listing. Dùng massage cơ bắp ở các vùng phù hợp; cần kiểm tra đầu massage, nguồn điện/pin và mức cường độ.', '203000'),
('3', '2', 'COCO-S03-C02-0023', 'Bút chì Gel kẻ mắt Derf không thấm nước, để trang điểm mắt', 'Màu sắc: Đen hoặc Nâu
