 CÔNG DỤNG:
 Làm sạch da nhẹ nhàng làm sạch lớp trang điểm mà không gây khô da; làm dịu da; duy trì tình trạng cân bằng của da; giúp da thông thoáng, sáng mịn.
 ƯU ĐIỂM:
 Tận dụng tối đa khả năng làm dịu da, làm mềm da và dưỡng ẩm cho da nhẹ nhàng làm sạch lớp trang điểm mà vẫn duy trì được tình trạng cân bằng của da, giúp da mềm dịu, không gây khô da, không
 Bảng thành phần an toàn, lành tính, không chứa parapen, không cồn khô, không hương liệu, không sulfate giúp hạn chế tối đa kích ứng cho da.
 CHỈ ĐỊNH: Phù hợp với mọi loại da.
 THÀNH PHẦN CHÍNH:
 Hydrogenated Olive oil:
 Olea Europaea (Olive) Fruit Oil: c
 Olea Europaea (Olive) Oil Unsaponifiables:
 Ethylhexyl Olivate:
 Lauryl Olivate:
 Olea Europaea (Olive) Leaf Extract (Chiết xuất lá Olive):
 tocopherols, phenols
 Hướng dẫn sử dụng
 Để sử dụng nước tẩy trang hiệu quả, bạn thấm dung dịch vào bông tẩy trang rồi lau nhẹ nhàng trên da, bắt đầu từ vùng mắt và môi, sau đó đến các vùng khác trên khuôn mặt theo chuyển động tròn từ dưới lên trên. Cuối cùng, rửa lại mặt với nước hoặc sữa rửa mặt để làm sạch hoàn toàn cặn bẩn còn sót lại và tiếp tục các bước dưỡng da tiếp theo
