('2', '3', 'COCO-S02-C03-0016', 'Nailbox thiết kế c232 mẫu đơn giản chụp kỉ yếu đi học, đi chơi Cebi.nailbox', 'Giới thiệu về thương hiệu: Cebi Nailbox là thương hiệu chuyên cung cấp móng giả thiết kế thủ công với hơn 5 năm kinh nghiệm. Chúng tôi tự hào mang đến các sản phẩm móng giả cao cấp, giúp bạn sở hữu bộ móng đẹp mắt chỉ trong vài phút mà không cần đến tiệm nail.
 Thiết kế và chất liệu: Sản phẩm của Cebi Nailbox có thiết kế sang trọng và độc đáo, với nhiều mẫu mã đa dạng từ phong cách tối giản đến những mẫu đính đá, ánh kim lấp lánh. Móng giả được làm từ nhựa cao cấp, đảm bảo an toàn cho móng thật, không gây kích ứng và dễ dàng tháo ra khi cần.
 Bộ sản phẩm bao gồm:
 10 móng giả trang trí sẵn.
 Keo dán hoặc miếng dán tạm thời.
 Bộ dụng cụ hỗ trợ như que đẩy da, dũa mini và bông tẩm cồn.
 Hướng dẫn sử dụng:
 1. Chuẩn bị: Làm sạch móng thật bằng bông tẩm cồn và đẩy nhẹ phần da thừa.
 2. Dán móng: Chọn móng giả phù hợp, bôi keo hoặc dùng miếng dán, đặt móng lên và giữ cố định trong vài giây.
 3. Chỉnh sửa: Sử dụng dũa mini để hoàn thiện bộ móng theo ý thích.
 Ưu điểm nổi bật:
 Tiết kiệm thời gian và chi phí: Không cần đến tiệm nail, bạn có thể tự làm đẹp tại nhà.
 Đa dạng phong cách: Phù hợp cho mọi dịp, từ đi làm, đi chơi đến dự tiệc.
 An toàn và dễ sử dụng: Chất liệu thân thiện, không gây hại cho móng thật và dễ dàng tháo ra khi cần.
 Chính sách đổi trả: Sản phẩm có thể được đổi trả trong vòng 15 ngày nếu có lỗi từ nhà sản xuất. Cebi Nailbox cam kết chất lượng với sản phẩm giống mô tả 80% và giao hàng nhanh chóng.', '55000'),
