 Màu sắc: Vàng, Xanh lá
 - Thiết kế bọt biển tiện lợi và đẹp mắt, miếng bọt biển mềm và đàn hồi giúp tán đều lớp nền và đệm khí một cách nhẹ nhàng và tự nhiên, tăng độ bám dính của kem nền và đệm khí cho da.
 - Bông phấn trang điểm, bông phấn dạng lỏng, bông phấn mềm mại, không gây kích ứng da
