 -Sản phẩm được 1 đổi 1 hàng lỗi trong vòng 6 tháng 
 -Bảo hành 24 tháng trên toàn quốc
 -Đội ngũ tư vấn tận tình 24/24 về các vấn đề khiếu nại , hoàn trả .
