('1', '5', 'COCO-S01-C05-0031', 'Máy Massage Rung Nóng X5, Đai massage giảm mỡ bụng hồng ngoại X5 Toàn Thân Cao Cấp', '-Máy Massage Rung Nóng X5, Đai massage giảm mỡ bụng hồng ngoại X5 Toàn Thân Cao Cấp
 -THÔNG TIN SẢN PHẨM: Đai Massage Rung Nóng X5 Giảm Mỡ Bụng, Toàn Thân Cao Cấp
 - Bộ sản phẩm gồm: 1 đai quấn massage, hộp điều khiển, 1 Adapter
 - Điện áp sử dụng: 220V/ 50hz
 - Điện áp adapter: 12V -1A
 - Chiều dài dây đai: 120cm
 - Kích thước hộp: 32cm x 15cm x 10cm
 - Màu sắc: xanh
 - Ưu Điểm Sản Phẩm
 - Đai Massage Rung Nóng X5 Giảm Mỡ Bụng, Toàn Thân
 - Đai massage bụng X5 sử dụng sóng siêu hồng ngoại có khả năng loại bỏ mỡ dư thừa trong cơ thể và không có tác dụng phụ.
 - Thiết kế 5 motor trải điều lên toàn thân máy, giúp rung massage tác động lên toàn vùng eo của người sử dụng, giảm mỡ cũng như massage điều tới các cơ trên vùng eo.
 - Đai massage X5 có 3 chế độ rung khác nhau giúp giảm nhanh mệt mỏi cũng như giảm nhanh mỡ thừa trên các vùng như: bụng, eo, đùi, mông, bắp tay, mông...
 - Bộ điều khiển thông minh để điều chỉnh nhiệt độ theo cơ thể, kích thích xung tần số thấp qua da, thâm nhập vào lớp chất béo và loại bỏ chất béo ở tần số cao.
 - Đai massage X5 có 2 trạng thái rung massage "rung mạnh" và "rung nhẹ" giúp cho người dùng tiện lợi hơn trong việc chọn chế độ rung phù hợp với từng vùng massage cũng như phù hợp với từng độ tuổi của người sử dụng (già hoặc trẻ).
 - Đai massage X5 giảm mỡ bụng có thiết kế gọn gàn và dể dàng mang đi mọi nơi, như đi du lịch hay đi công tác vẫn có thể mang theo, máy bỏ gọn gàng trong túi xách, ba lô... Bạn có thể sử dụng đai mọi lúc mọi nơi như khi làm việc, lúc xem tivi, hoặc trước khi đi ngủ...
 + Tác dụng 
 - Giúp bụng phẳng, eo thon, giảm mỡ tích tụ trong cơ thể một cách hiệu quả.
 - Đẩy mạnh tuần hoàn máu, thúc đẩy sự trao đổi chất.
 - Giúp massage toàn thân như: bụng, đùi, vai, lưng, mông..., tạo cảm giác thư giãn kết hợp giảm mỡ thừa hiệu quả
 - Giúp đùi mông và bắp chân săn chắc, quyến rũ
 - Giúp giảm mỡ cơ bụng, hông, mông, đùi.
 + HƯỚNG DẪN SỬ DỤNG: 
 – Bật máy và đeo máy vào vùng cần massage và kết nối lại với nhau, lưu ý đừng quấn chật quá hoặc lỏng quá.
 – Lấy cục adapter kết nối với máy, và sau đó kết nối với điên áp nguồn (220V/50hz).
 – Intersity: Tốc độ hoặc cường độ rung của máy, máy có 2 tốc độ “Weak” rụng với trạng thái rung trung bình, “Strong” 
  máy rung với tốc độ mạnh nhất, “Off” trạng thái tắt chế độ rung.
 – Nên chọn chế độ massage từ thấp lên cao
 – Trong quá trình massage thường thì các lần tập đầu tiên có cảm giác ngứa, và đỏ nơi vùng da đang massage đó là 
  trạng thái bình thường, vài lần tập luyện sau sẽ hết.
 – Không ngâm trực tiếp vào nước, cũng như đem giặt máy, chỉ dủng giẻ lau sạch máy và để khô tự nhiên, không đem 
