('2', '5', 'COCO-S02-C05-0031', 'Máy massage bụng kinh Unpublic, Giảm đau nhanh, Làm ấm bụng, Lưng, Tử cung cho phụ nữ đến kì', 'Máy massage bụng kinh Unpublic, tên listing mô tả chức năng làm ấm vùng bụng và lưng cho phụ nữ trong kỳ kinh. Cần kiểm tra nguồn điện, mức nhiệt, thời gian tự ngắt và hướng dẫn an toàn; không coi là thiết bị điều trị bệnh.', '120000'),
('1', '2', 'COCO-S01-C02-0027', 'Son bóng Seven notes màu juicy đậm đặc chống dính chống thấm dưỡng ẩm', 'Son bóng Seven Notes màu Juicy theo tên listing, chất son được mô tả đậm đặc, dưỡng ẩm, chống dính và chống thấm nước. Dùng tạo hiệu ứng bóng môi; dung tích và mã màu cần chọn theo phân loại.', '40000'),
('2', '3', 'COCO-S02-C03-0020', 'Bông tẩy trang 222 miếng 3 lớp Cotton pads', 'Bông tẩy trang quy cách 222 miếng, cấu trúc 3 lớp cotton pads theo tên listing. Dùng thấm nước tẩy trang, toner hoặc sản phẩm chăm sóc da; thương hiệu và thành phần sợi chưa được nêu rõ trong tên.', '35000'),
('3', '5', 'COCO-S03-C05-0031', 'Mini Di Động EMS Cổ Máy Mát Xa Điện Cổ Cáng Để Giảm Đau Cổ Tử Cung Và Thư Giãn Vai Miếng Dán Massage', 'Sự chỉ rõ:
 Tên sản phẩm: Magic paste
 Điện áp: 3.7V
 Cách sử dụng: A-F (8 chế độ) 19 bánh răng
 Tần số: 1-100HZ
 Giờ làm việc: 15 phút
 Đầu ra: tối đa 35mA
 Dung lượng pin: 200mAH
 Tần số: 1 ~ 100Hz
 Các tính năng:
 * 100% thương hiệu mới và chất lượng cao.
 * Phần Massage: cổ / lưng / eo / hông / chân và các bộ phận khác.
 * 8 chế độ & 19 cấp độ: Có các mức cường độ khác nhau cho mỗi chế độ (Khai thác, xoa bóp, xoa bóp, bóp, gõ, nhào trộn, đào tạo, tạo hình) Người dùng có thể lựa chọn cường độ khác nhau tùy theo nhu cầu cá nhân.
 * Giúp giảm mệt mỏi, thư giãn cơ bắp, cải thiện lưu thông máu và đốt cháy chất béo.
 * Không giống như các thiết bị massage thông thường hiện có chỉ chà xát bên ngoài cơ, máy mát xa còn dùng để kích thích bên trong cơ, giúp tăng cường tuần hoàn máu hiệu quả giúp phục hồi nhanh chóng sau mệt mỏi.
 * Kích thước nhỏ, nhẹ, dễ mang theo và cất giữ.
 Hướng dẫn:
 1.Vặn máy chủ bằng miếng gel.
 2.Mở lớp màng trong suốt trên miếng gel.
 3.Gắn thiết bị vào khu vực bạn cần xoa bóp.
 4.Nhấn nút "+" để bật nó lên.
 5.Nhấn nút "M" để chọn chế độ mong muốn.
 6.Điều chỉnh theo cường độ xoa bóp phù hợp với bạn. Tiếp tục nhấn "+" để tăng cường độ và "-" để giảm cường độ.
 Lưu ý: miếng dán là hàng tiêu dùng, vì miếng dán không dính nên người có da trung tính cần thay miếng dán sau khoảng 20 lần, người có da dầu cần thay miếng dán sau nhiều hơn Mười lần.', '168800'),
('2', '2', 'COCO-S02-C02-0027', 'Berberbeni Mắt Sáng Slim Eyeliner Gel Bút Màu Mịn Render Ngọc Trai Mịn Nhấp Nháy Chống Thấm Nước Giữ Trang Điểm Không Dễ Dàng', 'Tên sản phẩm: Kẻ mắt Berberi Slim
 Đầu rất mịn, lên màu trong một nét, Màu sắc phong phú, nước mịn
 Không thấm nước, chống mồ hôi, suốt cả ngày dài
 Đầu tròn mỏng, mịn và dễ sử dụng, mềm và cứng vừa phải không dễ gãy, kết cấu mịn và mịn, màu sắc phong phú, đúc một nét
 Màu sắc của sản phẩm liên quan đến ánh sáng xung quanh và các khía cạnh khác. Điều bình thường là có thể có sự khác biệt nhỏ về màu sắc giữa các lô khác nhau
 Cách dùng: Lắc bút trước khi sử dụng để đảm bảo chất lỏng lưu thông, nhẹ nhàng nhấc mí mắt lên gốc mi để lấp đầy khoảng trống mí mắt
 Các vấn đề về ánh sáng có thể gây ra quang sai màu và các vấn đề khác', '21200'),
('1', '5', 'COCO-S01-C05-0032', 'Gối ngải cứu cổ vai gáy cắm điện sưởi ấm giúp giảm đau  kê cổ thảo dược hương thơm dễ chịu', 'Gối Thảo Dược Kê Cổ Gối Đầu Ngải Cứu Có Cắm Điện Làm Nóng Cổ Spa Hương Thơm Thảo Mộc Giúp Giảm Đau Nhức Cổ Vai Cho Giấc Ngủ Ngon
 ☘Gối Thảo Dược Ngải Cứu có vỏ gối làm bằng chất liệu vải Nhung êm ái . Gối gồm 2 phần: Gối có phần kê cổ cắm điện giúp làm nóng cổ vai gáy giúp tạo cảm giác êm ái thoải mái khi nằm.☘
 1. Gối có tác dụng chính là giúp ngủ ngon và thư giãn nên mức nhiệt độ thiết kế của gối là 35 - 45 độ C. Mức nhiệt này lý tưởng giúp bạn dễ dàng đi vào giấc ngủ ngon và giúp bớt đau mỏi. Do vậy gối sẽ không quá nóng như gối chườm. Nếu bạn cần mua loại gối có nhiệt độ cao trên 70 độ C như gối chườm nóng nhiều xin vui lòng lựa chọn sản phẩm khác.
 Gối Ngải Cứu Thảo Dược Trung Hoa xanh dương Chống Đau Mỏi Vai Gáy, Massage Chuyên Sâu - Spa Dưỡng Sinh
 Gối Thảo Dược Ngải Cứu có độ cứng nhất định và không thể êm bằng gối đệm bông, nhưng nó vẫn có độ êm đặc chưng và gối thoát hơi, thông thoáng, hương thảo dược thơm dịu, hút ẩm khử mùi tốt.
 Gối Ngải Cứu, Gối Ngủ Chống Đau Vai Gáy 
 - Rất tốt cho người hay đau mỏi cổ vai gáy hoặc mất ngủ
 - Bảo vệ cột sống cổ,
 - Có thể tháo rời vỏ gối ra để giặt sạch
 ----------
 - Thiết kế gối vừa vặn với cột sống cổ, massage thoải mái, nâng đỡ cơ thể, giúp bạn có một giấc ngủ ngon và lành mạnh,
 - Gối gồm 2 phần: Phần gối chữ nhật và phần gối tròn nâng đỡ cổ, có thể tách rời để sử dụng
 Phần gối tròn có thể sử dụng để kê lưng, nếu bị đau lưng
 Xin vui lòng cân nhắc kỹ trước khi mua để tránh trường hợp khi mua không đúng như mong muốn dẫn đến đổi trả hàng không cần thiết vì gối ngải rất nặng . Việc vận chuyển và hoàn hàng sẽ gây tốn kém cho quý khách và cho shop. Xin cảm ơn ạ.
 ☘ Gối điện ngải có 03 mức độ nóng và tùy chỉnh thời gian gối nóng dài nhất là 60 phút, sau thời gian 60 phút điện sẽ tự ngắt để tiết kiệm điện..
 ☘Gối Thảo Dược có ruột với thành phần chính là thân và cành cây ngải cứu được băm thành các khúc nhỏ, khi gối sẽ cảm nhận mùi thơm thảo dược nhẹ nhàng dễ chịu.
 ☘Gối Thảo Dược ngải cứu giúp nâng đỡ phần cổ và đầu, giúp giảm hẳn đau mỏi cổ vai, đau cứng cổ sau giấc ngủ. Đem lại chất lượng giấc ngủ tốt hơn.
 ☘Gối ngải cứu thảo mộc giúp hút ẩm, thoát hơi tốt, mang lại cảm giác thư giãn, giúp bạn dễ dàng đi vào giấc ngủ ngon và sâu hơn
