('2', '5', 'COCO-S02-C05-0032', 'Gậy gãi lưng inox rút gọn kéo dài, kéo dài tiện dụng hình bàn tay-MCKES', 'Gậy gãi lưng inox rút gọn kéo dài, kéo dài tiện dụng hình bàn tay-MCKES
 Mô tả Sản phẩm:
 -Thiết kế nhỏ gọn, tiện lợi
 -Giúp giảm ngứa ở những vùng khó tiếp cận
 -Có thể thu gọn thành cây anten nhỏ có móc.
 -Màu sắc: vàng
 -Kích thước: Chiều dài đầy đủ 42cm, tối thiểu 16.5cm, chiều rộng 3cm
 -Chất liệu: Thép không gỉ + nhựa
 -Gói hàng bao gồm:1 cái
 Mô tả Sản phẩm:
 Các sản phẩm trong cửa hàng đều được làm sẵn và sẽ được đóng gói ngay khi khách hàng đặt hàng.
 Có hàng, giao hàng nhanh
 Mọi thắc mắc về sản phẩm vui lòng nhắn tin trực tiếp tới cửa hàng để được giải đáp
 Vui lòng lưu ý:
 Sản phẩm được đo bằng tay, có thể có sai số 1-3 cm. Hy vọng bạn có thể hiểu và thông cảm, sẽ được chân thành đánh giá cao.
 Xin lưu ý rằng do hiệu ứng ánh sáng, cài đặt độ sáng / độ tương phản của màn hình, v.v., có thể có một số khác biệt nhỏ trong tông màu của ảnh trang web và sản phẩm thực tế.', '12500'),
('3', '5', 'COCO-S03-C05-0032', 'Miếng Dán Massage Xung Điện EMS, Máy Massage Toàn Thân 8 Chế Độ 19 Cường Độ Giảm Đau Nhức Hiệu Quả', 'Miếng Dán Massage Xung Điện EMS, Máy Massage Toàn Thân 8 Chế Độ 19 Cường Độ Giảm Đau Nhức Hiệu Quả
 Miếng Dán Massage Xung Điện EMS Tích Hợp 8 Chế Độ, Giảm Nhức Mỏi Cổ Vai Gáy Hiệu Quả, Thư Giãn Cơ
 - Pin Sạc USB: Tích hợp sạc USB, dùng hết pin chỉ cần cắm dây sạc như điện thoại bình thường. Không cần thay pin. Thời gian sạc đầy pin 40-60 phút. Sử dụng liên tục từ 100 - 160 phút. 
 ✔️ Miếng dán mỏng nhẹ ôm khít vào vùng cổ, vai gáy, tay chân
 ✔️ Xung điện EMS cực mạnh với tốc độ 1000 lần/phút
 ✔️ Làm mềm cơ, xua tan các cơn đau mỏi nhanh chóng
 ✔️ Dòng điện EMS tần số từ 1-100Hz tùy chỉnh
 ✔️ Massage linh hoạt với 8 kiểu và 19 mức cường độ
 ✔️ Có thể sử dụng với nhiều vị trí trên cơ thể
 ✔️ Thiết bị rất gọn nhẹ, có thể mang theo bất cứ đâu
 🎯 Lưu ý:
 - Khi massage bạn nên nới lỏng các cơ bắp để liệu pháp massage được hiệu quả hơn.
 - Miếng dán sau khi sử dụng nên dùng miếng dán bảo vệ dán vào, tránh dơ và khô lớp gel miếng dán.
 - Khi mở máy ra khỏi miếng dán nên dùng một lực vừa đủ tránh làm hư miếng dán.
 - Miếng dán sử dụng dòng điện xung để massage nên những bạn chưa từng sử dụng vui lòng tìm hiểu trước hoặc nhắn shop tư vấn nha.
 🎯 Thông số kỹ thuật :
 - Điện áp: Pin Lithium 3.7V
 - Chế độ massage: 8 Mode
 - Cường độ: 19 Mức cường độ
 - Tần số: 1-100Hz
 - Thời gian sử dụng: 15 phút (Tự ngắt bảo vệ - Bật lại nếu tiếp tục sử dụng)
 - Điện áp đầu ra: 35mA
 - Pin: 200mAh
