('3', '2', 'COCO-S03-C02-0027', 'Bút Chì Kẻ Lông Mày Lõi Gỗ Cứng Chống Nước & Nhòe', 'Chì kẻ mày không thấm nước & bong tróc - Chống lem, lâu trôi, thân thiện với người mới bắt đầu
 Điểm nổi bật của sản phẩm:
 ✔ Không thấm nước & chống thấm mồ hôi - Luôn hoàn hảo cả ngày (mặc lên đến 24H), ngay cả trong thời tiết ẩm ướt.
 ✔ Thiết kế Peel-Off - Không cần mài! Chỉ cần bóc giấy gói để có một mẹo chính xác.
 ✔ Các nét giống như tóc tự nhiên - Đầu siêu mịn tạo hiệu ứng microblade cho đôi lông mày đầy đặn hơn.
 ✔ Smudge-Proof Formula - Không phai màu hoặc chuyển màu, hoàn hảo cho da dầu.
 ✔ Thân thiện với người mới bắt đầu - Dễ dàng kiểm soát cho đôi lông mày hoàn hảo mọi lúc.
 Cách sử dụng:
