 Tại sao nên chọn Chì kẻ mày này?
 ✨ Không lãng phí - Thiết kế bóc vỏ đảm bảo không có sản phẩm nào bị lãng phí.
 ✨ Thân thiện với du lịch - Không cần mài, hoàn hảo cho việc chỉnh sửa khi đang di chuyển.
 ✨ Vegan & Cruelty-Free - An toàn cho mọi loại da.
 Hoàn hảo cho:
 • Lông mày tự nhiên hàng ngày
 • Trang điểm chống phòng tập thể dục
