('3', '3', 'COCO-S03-C03-0020', 'Sơn Móng Tay gel uv 9d Mắt Mèo Lấp Lánh Cho Nữ diy', 'Sơn gel UV hiệu ứng mắt mèo 9D, tạo hiệu ứng ánh sáng/nhũ khi sử dụng nam châm chuyên dụng. Cần dùng đèn UV/LED tương thích để đóng rắn gel; màu và dung tích tùy phân loại.', '15700'),
