('2', '2', 'COCO-S02-C02-0028', 'Son Dưỡng Môi Mỡ Hươu Astrid Fullsize 4.7g', 'Astrid là một thương hiệu mỹ phẩm của Séc, đã ra đời cách đây tới 150 năm. Một trong các sản phẩm nổi tiếng nhất của Astrid phải kể đến là Son dưỡng môi mỡ hươu.
 Không chỉ tại Việt Nam mà tại nước ngoài son dưỡng môi mỡ hươu Astrid đều rất phổ biến, và được biết đến như một sản phẩm son dưỡng không màu có tác dụng dưỡng ẩm và phục hồi cho những đôi môi khô nẻ.
 ✨ Thành phần & Công dụng
 - Vitamin E tự nhiên giúp dưỡng ẩm cho môi, chăm sóc môi tối ưu, tăng cường độ đàn hồi và săn chắc môi.
 - Chiết xuất mỡ hươu cung cấp các chất chống oxi hóa giúp tái tạo da môi, phục hồi các hư tổn do thời tiết, tia tử ngoại và các tác nhân gây hại khác, giúp hạn chế tình trạng lão hóa da môi, giúp đôi môi luôn căng mọng, mềm mại.
 - Dầu kakao cung cấp dưỡng chất dưỡng ẩm cho môi, thúc đẩy quá trình tái tạo môi giúp môi luôn căng mọng mịn màng đầy sức sống.
 Ngoài ra, bạn có thể sử dụng son dưỡng Astrid Lip Balm để đánh lót trước khi dùng son thỏi, làm tươi thêm màu son môi, làm bền thêm màu son, giúp son lâu trôi.
 ✨ Hướng dẫn sử dụng
 - Thoa son dưỡng trước khi đi ngủ ( có thể dùng thay cho mặt nạ ngủ môi ).
 - Dùng hàng ngày bất cứ khi nào môi bạn khô để có đôi môi mềm mại.
 MÔ TẢ SẢN PHẨM
 - Khối lượng: 4.7g
 - Xuất xứ: Cộng hòa Séc
 - Hạn sử dụng: 3 năm kể từ ngày sản xuất', '35000'),
('3', '2', 'COCO-S03-C02-0028', 'Má Hồng Phấn Má Hồng Trang Điểm Má Hồng Nội Địa Trung Mềm Mịn Bảng Phấn Má Hồng YUKIBLOOM', 'Má Hồng Phấn Má Hồng Trang Điểm Má Hồng Nội Địa Trung Mềm Mịn Bảng Phấn Má Hồng YUKIBLOOM
