('1', '3', 'COCO-S01-C03-0021', '120 Cái / túi Ba Lê Móng Tay Giả Hoàn Toàn Trong Suốt Acrylic Móng Tay Bộ Bấm Vào Móng Tay Đầu Kích Thước Hỗn Hợp Giả Ongles Fantasie', '❥ Bạn thân mến, ❥ Chào mừng đến với CỬA HÀNG CỦA TÔI ❥ Bạn có thể có một thời gian mua sắm tốt ở đây ❥ Đơn đặt hàng sẽ được gửi đi trong vòng 2 ngày. ❥ Freebies có sẵn cho mọi đơn đặt hàng!! ❥ Theo dõi cửa hàng của chúng tôi, nhận thêm chiết khấu và nhận được nhiều chiết khấu hơn trong tương lai! ❥ Có bất kỳ câu hỏi nào, xin vui lòng gửi tin nhắn cho chúng tôi! Chúng tôi rất vui khi được giúp bạn!', '24843'),
('2', '5', 'COCO-S02-C05-0033', '[ HÀNG LOẠI 1 ] BỘ GIÁC HƠI KHÔNG CẦN LỬA  12 LY KÈM 1 ỐNG BƠM CHUYÊN DỤNG', '* THÔNG TIN SẢN PHẨM : 
