('3', '3', 'COCO-S03-C03-0021', 'XUANXIANG Set 13 Cọ Trang Điểm Lông Mềm Chất Lượng Cao Dịu Dàng Dễ Mang Theo HRY24102ME', 'Set 13 cọ trang điểm XUANXIANG, tên listing mô tả lông mềm và thiết kế dễ mang theo. Dùng cho các bước trang điểm cơ bản; hình dạng từng cọ, chất liệu lông và túi đựng cần đối chiếu bộ thực tế.', '14900'),
('1', '2', 'COCO-S01-C02-0029', 'Nước tẩy trang thuần chay bí đao Cobe và Dầu tẩy trang thuần chay Hoa Trà Cobe tẩy sạch bụi bẩn, an toàn cho mọi làn da', 'Sản phẩm tẩy trang Cobe gồm nước tẩy trang chiết xuất bí đao và dầu tẩy trang chiết xuất hoa trà theo tên listing. Dùng làm sạch lớp trang điểm/bụi bẩn; chưa rõ đây là combo hai sản phẩm hay hai phân loại, cần kiểm tra dung tích từng lựa chọn.', '120000'),
('2', '2', 'COCO-S02-C02-0029', 'Mềm Phấn Phủ / Phấn Phủ Che Khuyết Điểm / Phấn Phủ Kiềm Dầu Kháng Nước Lâu Trôi Trong Suốt / Tiệc Tùng', 'Mô tả: Hiệu quả: Kiểm soát dầu và trang điểm, che giấu lỗ chân lông và cải thiện tông màu da. Loại da phù hợp: Phổ thông. Thông số kỹ thuật:
