 Thiết kế nhỏ gọn: Kích thước vừa phải, cấu trúc nhỏ gọn, tiện lợi khi mang theo.', '185000'),
('1', '3', 'COCO-S01-C03-0022', 'LILYCUTE Sơn Móng Tay gel uv 7ml Sơn Gel Màu Phổ Biến Cho Salon Tại Nhà Nail Art', 'Sơn gel LILYCUTE dung tích 7 ml, dùng sơn móng và đóng rắn bằng đèn UV/LED theo dòng sản phẩm. Có nhiều màu lựa chọn; cần chọn đúng mã màu/hiệu ứng trong phân loại.', '18700'),
('3', '5', 'COCO-S03-C05-0033', 'Máy massage cầm tay mini đấm lưng mát xa trị liệu cổ vai gáy 4 đầu 6 chế độ', 'CÁCH KHỞI ĐỘNG MÁY: nhấn nút và giữ nút trong 3 giây
