('1', '5', 'COCO-S01-C05-0034', 'Gậy gỗ 20 bi lăn massage đả thông kinh lạc ,giảm béo đánh tan mỡ bụng', 'Bông cắt Bạch Tuyết là sản phẩm được sản xuất theo công nghệ xử lý màng bông Spunlace, bông mịn sạch tinh tế, giúp hạn chế tối đa xơ thừa dính trên bề mặt vết thương
 Bông cắt là một trong những dòng bông y tế, được sản xuất từ bông xơ tự nhiên, không pha sợi Polyester nên bảo đảm an toàn với da nhạy cảm.
 Màng bông được xử lý bằng công nghệ Spunlace giúp bông mềm, mịn, chắc và đàn hồi tốt. Công nghệ Spunlace giúp xử lý tới 99% xơ thừa trên bề mặt và độ thấm hút đạt hiệu quả cao hơn.
 Quá trình xử lý màng bông sử dụng tia nước áp lực cao không dùng hóa chất nên hoàn toàn không gây ra kích ứng cho làn da nhạy cảm.
 Đối với trường hợp đặc biệt trong phẫu thuật, tiêm, tiệt trùng bằng công nghệ E.O gas.
 Sản phẩm tiện dụng trong các trường hợp cấp thiết được các bệnh viện, trung tâm y tế, công ty thiết bị y tế… tín nhiệm, dùng trong phẫu thuật, xử lý vết thương.
 Ngoài ra, bông cắt với kích thước nhỏ hơn còn là sản phẩm được các mẹ yêu chuộng dùng vệ sinh bé thay cho khăn giấy ướt không gây hâm hay kích ứng cho da bé.', '152200'),
('2', '5', 'COCO-S02-C05-0034', 'máy massage cầm tay , massage cổ vai gáy 6 Cấp Độ Chuyên Sâu Đa Năng , máy đấm lưng mát xa đau nhức vai gáy', 'Máy massage cầm tay dùng cho cổ vai gáy, tên listing ghi 6 cấp độ chuyên sâu. Dùng massage cơ bắp; thông số công suất, đầu massage và nguồn điện cần đối chiếu sản phẩm thực tế.', '369000'),
('3', '5', 'COCO-S03-C05-0034', 'Miếng Dán Massage Xung Điện HGMART 8 Chế Độ - Máy Massage Toàn Thân Cao Cấp [ HÀNG TỐT ]', 'Miếng Dán Massage Xung Điện HGMART 8 Chế Độ - Máy Massage Toàn Thân Cao Cấp [ HÀNG TỐT ]
 ====================
 ✔️ Massage linh hoạt với 8 kiểu và 19 mức cường độ
 ✔️ Có thể sử dụng với nhiều vị trí trên cơ thể
 ✔️ Thiết bị rất gọn nhẹ, có thể mang theo bất cứ đâu
 ✔️ Miếng dán mỏng nhẹ ôm khít vào vùng cổ, vai gáy, tay chân
 ✔️ Xung điện EMS cực mạnh với tốc độ 1000 lần/phút
 ✔️ Làm mềm cơ, xua tan các cơn đau mỏi nhanh chóng
 ✔️ Dòng điện EMS tần số từ 1-100Hz tùy chỉnh
 =======================
 🎯 Lưu ý:
 - Khi massage bạn nên nới lỏng các cơ bắp để liệu pháp massage được hiệu quả hơn.
 - Miếng dán sau khi sử dụng nên dùng miếng dán bảo vệ dán vào, tránh dơ và khô lớp gel miếng dán.
 - Khi mở máy ra khỏi miếng dán nên dùng một lực vừa đủ tránh làm hư miếng dán.
 - Miếng dán sử dụng dòng điện xung để massage nên những bạn chưa từng sử dụng vui lòng tìm hiểu trước hoặc nhắn shop tư vấn nha.
 ======================
 🎯 Thông số kỹ thuật :
 - Điện áp: Pin Lithium 3.7V
 - Chế độ massage: 8 Mode
 - Cường độ: 19 Mức cường độ
 - Tần số: 1-100Hz
 - Thời gian sử dụng: 15 phút (Tự ngắt bảo vệ - Bật lại nếu tiếp tục sử dụng)
 - Điện áp đầu ra: 35mA
 - Pin: 200mAh
 ========================
 Gia Dụng Diễm Trang Cam Kết:
 - Đổi trả hàng miễn phí trên tất cả mặt hàng 1 - 1 
