('1', '3', 'COCO-S01-C03-0023', '❤️【8.15】Ưu đãi giới hạn thời gian❤️Giao hàng trong ngày Máy Tính Để Bàn Gương Trang Điểm ins Phong Cách Influencer Cô Gái Trái Tim Để Bàn Hộ Gia Đình Có Thể Đứng Ký Túc Xá Sinh Viên Gương Trang Điểm Hai Mặt', 'Gương trang điểm để bàn hai mặt, phong cách influencer/INS theo tên listing. Có thể đặt trên bàn để soi và trang điểm; kích thước, độ phóng đại, chất liệu chân đế và khả năng gấp/gập tùy mẫu.', '37900'),
('2', '3', 'COCO-S02-C03-0023', 'UR SUGAR Sơn Thạch Gel 15ml Sơn Gel Sơn Móng Tay Sơn Thạch Sơn Gel Thạch Sơn Móng Thạch Gel Nail Art', 'Sơn thạch gel UR SUGAR dung tích 15 ml, tạo hiệu ứng màu trong kiểu jelly trên móng. Dùng với đèn UV/LED để đóng rắn; màu sắc và độ trong phụ thuộc mã màu.', '39000'),
('1', '5', 'COCO-S01-C05-0035', 'máy massage cổ vai gáy 6D BẢN CAO CẤP CÓ ĐÈN HỒNG NGOẠI , khăn choàng massage cổ vai gáy', 'máy massage cổ vai gáy 6D BẢN CAO CẤP CÓ ĐÈN HỒNG NGOẠI , khăn choàng massage cổ vai gáy
 💥 hướng dẫn sử dụng máy:
 - ấn giữ nút nguồn trong 5 giây để máy khởi động
